1	export const CHECKRIDE_FEE_INVOICE_STATUS = 'Completed';
2	
3	type CheckrideFeeLineItem = Record<string, unknown> & {
4	  description: string;
5	  quantity: number;
6	  rate: number;
7	  amount: number;
8	};
9	
10	function finiteNumber(value: unknown): number | null {
11	  if (typeof value === 'number' && Number.isFinite(value)) return value;
12	  if (typeof value === 'string' && value.trim()) {
13	    const parsed = Number(value);
14	    if (Number.isFinite(parsed)) return parsed;
15	  }
16	  return null;
17	}
18	
19	/**
20	 * Converts legacy checkride fee line items (stored in cents as
21	 * unitAmount/total) to the invoice UI's canonical dollar-based shape.
22	 */
23	export function normalizeCheckrideFeeLineItems(input: {
24	  amountCents: number;
25	  description?: string | null;
26	  lineItems?: unknown;
27	}): CheckrideFeeLineItem[] {
28	  const fallbackAmount = input.amountCents / 100;
29	  const fallbackDescription = input.description?.trim() || 'Checkride Fee';
30	  const sourceItems = Array.isArray(input.lineItems)
31	    ? input.lineItems.filter(
32	        (item): item is Record<string, unknown> =>
33	          Boolean(item) && typeof item === 'object' && !Array.isArray(item),
34	      )
35	    : [];
36	  const items =
37	    sourceItems.length > 0
38	      ? sourceItems
39	      : [{ description: fallbackDescription }];
40	
41	  return items.map((item) => {
42	    const quantity = Math.max(1, finiteNumber(item.quantity) ?? 1);
43	    const legacyRate = finiteNumber(item.unitAmount);
44	    const legacyAmount = finiteNumber(item.total);
45	    const explicitRate = finiteNumber(item.rate);
46	    const explicitAmount = finiteNumber(item.amount);
47	    const amount =
48	      explicitAmount ??
49	      (legacyAmount !== null ? legacyAmount / 100 : null) ??
50	      (explicitRate !== null
51	        ? explicitRate * quantity
52	        : legacyRate !== null
53	          ? (legacyRate / 100) * quantity
54	          : fallbackAmount);
55	    const rate =
56	      explicitRate ??
57	      (legacyRate !== null ? legacyRate / 100 : null) ??
58	      amount / quantity;
59	    const persistedFields = Object.fromEntries(
60	      Object.entries(item).filter(
61	        ([key]) => key !== 'unitAmount' && key !== 'total',
62	      ),
63	    );
64	
65	    return {
66	      ...persistedFields,
67	      description:
68	        typeof item.description === 'string' && item.description.trim()
69	          ? item.description.trim()
70	          : fallbackDescription,
71	      quantity,
72	      rate,
73	      amount,
74	    };
75	  });
76	}
77	
78	export function isCheckrideFeeInvoice(metadata: unknown): boolean {
79	  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) {
80	    return false;
81	  }
82	
83	  const type = (metadata as Record<string, unknown>).type;
84	  return (
85	    typeof type === 'string' &&
86	    type
87	      .trim()
88	      .toLowerCase()
89	      .replace(/[\s-]+/g, '_') === 'checkride_fee'
90	  );
91	}
92	
93	export function shouldCompletePendingCheckrideFeeInvoice(invoice: {
94	  status: string | null;
95	  metadata: unknown;
96	}): boolean {
97	  return (
98	    invoice.status?.trim().toLowerCase() === 'pending' &&
99	    isCheckrideFeeInvoice(invoice.metadata)
100	  );
101	}
102	
103	export function completedCheckrideFeeMetadata(
104	  metadata: unknown,
105	  completedAt: Date,
106	): Record<string, unknown> {
107	  const existing =
108	    metadata && typeof metadata === 'object' && !Array.isArray(metadata)
109	      ? (metadata as Record<string, unknown>)
110	      : {};
111	  const timestamp = completedAt.toISOString();
112	
113	  return {
114	    ...existing,
115	    invoiceDate:
116	      typeof existing.invoiceDate === 'string' && existing.invoiceDate
117	        ? existing.invoiceDate
118	        : timestamp,
119	    completedAt: timestamp,
120	    autoBilled: true,
121	    signoffRequired: false,
122	  };
123	}
