1	export type BillingSignOffGateStatus =
2	  | 'not_required'
3	  | 'signed'
4	  | 'pending'
5	  | 'expired'
6	  | 'missing_deadline'
7	  | 'invalid_deadline';
8	
9	export interface BillingSignOffGateInput {
10	  invoiceStatus?: string | null;
11	  signedOff?: boolean | null;
12	  signOffRequired?: boolean | null;
13	  signoffDeadline?: Date | string | null;
14	  now?: Date | number;
15	}
16	
17	export interface BillingSignOffGateDecision {
18	  status: BillingSignOffGateStatus;
19	  blocked: boolean;
20	  autoFinalizeEligible: boolean;
21	  deadline?: Date;
22	  reason?: string;
23	}
24	
25	const PENDING_INVOICE_STATUSES = new Set([
26	  'pending',
27	  'pending review',
28	  'pending approval',
29	  'pending sign-off',
30	]);
31	
32	function toTime(value: Date | number | undefined): number {
33	  if (value instanceof Date) return value.getTime();
34	  if (typeof value === 'number') return value;
35	  return Date.now();
36	}
37	
38	function parseDeadline(deadline: Date | string | null | undefined): {
39	  provided: boolean;
40	  deadline?: Date;
41	  valid: boolean;
42	} {
43	  if (deadline === null || deadline === undefined || deadline === '') {
44	    return { provided: false, valid: false };
45	  }
46	  const parsed = deadline instanceof Date ? deadline : new Date(deadline);
47	  if (Number.isNaN(parsed.getTime())) {
48	    return { provided: true, valid: false };
49	  }
50	  return { provided: true, deadline: parsed, valid: true };
51	}
52	
53	export function isBillingPendingStatus(status: string | null | undefined) {
54	  return PENDING_INVOICE_STATUSES.has(String(status ?? '').toLowerCase());
55	}
56	
57	export function evaluateBillingSignOffGate(
58	  input: BillingSignOffGateInput,
59	): BillingSignOffGateDecision {
60	  const status = String(input.invoiceStatus ?? '').toLowerCase();
61	  const pendingLike = isBillingPendingStatus(status);
62	  const signOffRequired =
63	    input.signOffRequired ??
64	    (status === 'pending sign-off' || input.signoffDeadline != null);
65	
66	  if (!pendingLike || !signOffRequired) {
67	    return {
68	      status: 'not_required',
69	      blocked: false,
70	      autoFinalizeEligible: false,
71	    };
72	  }
73	
74	  if (input.signedOff === true) {
75	    return { status: 'signed', blocked: false, autoFinalizeEligible: true };
76	  }
77	
78	  const parsed = parseDeadline(input.signoffDeadline);
79	  if (!parsed.provided) {
80	    return {
81	      status: 'missing_deadline',
82	      blocked: true,
83	      autoFinalizeEligible: false,
84	      reason: 'Sign-off is pending but no timeout deadline is available.',
85	    };
86	  }
87	  if (!parsed.valid || !parsed.deadline) {
88	    return {
89	      status: 'invalid_deadline',
90	      blocked: true,
91	      autoFinalizeEligible: false,
92	      reason: 'Sign-off is pending but the timeout deadline is invalid.',
93	    };
94	  }
95	
96	  if (parsed.deadline.getTime() > toTime(input.now)) {
97	    return {
98	      status: 'pending',
99	      blocked: true,
100	      autoFinalizeEligible: false,
101	      deadline: parsed.deadline,
102	      reason: 'Sign-off is still pending.',
103	    };
104	  }
105	
106	  return {
107	    status: 'expired',
108	    blocked: false,
109	    autoFinalizeEligible: true,
110	    deadline: parsed.deadline,
111	  };
112	}
