1	const MANUAL_MARK_PAID_BLOCKED_STATUSES = new Set(['cancelled', 'draft']);
2	
3	export const MANUAL_MARK_PAID_REFERENCE_PREFIX = 'manual-mark-paid:';
4	
5	export type ManualMarkPaidCandidate = {
6	  amount: number;
7	  status: string | null | undefined;
8	  paidAt?: Date | null;
9	  manuallyMarkedPaid?: boolean | null;
10	  completedPaidCents: number;
11	};
12	
13	/**
14	 * Return the amount still required to manually settle an invoice, or null when
15	 * the invoice is not eligible. `paidAt` is deliberately not an eligibility
16	 * gate: legacy imported invoices can have paidAt set without either a payment
17	 * record or the manually-marked-paid flag, and the manual action must repair
18	 * that incomplete state.
19	 */
20	export function manualMarkPaidRemainingCents(
21	  candidate: ManualMarkPaidCandidate,
22	): number | null {
23	  if (candidate.manuallyMarkedPaid) return null;
24	  if (
25	    MANUAL_MARK_PAID_BLOCKED_STATUSES.has(
26	      String(candidate.status ?? '').toLowerCase(),
27	    )
28	  ) {
29	    return null;
30	  }
31	
32	  const amount = Number.isFinite(candidate.amount)
33	    ? Math.max(0, Math.round(candidate.amount))
34	    : 0;
35	  const completedPaidCents = Number.isFinite(candidate.completedPaidCents)
36	    ? Math.max(0, Math.round(candidate.completedPaidCents))
37	    : 0;
38	  const remaining = Math.max(0, amount - completedPaidCents);
39	  return remaining > 0 ? remaining : null;
40	}
41	
42	export function manualMarkPaidReference(invoiceId: string): string {
43	  return `${MANUAL_MARK_PAID_REFERENCE_PREFIX}${invoiceId}`;
44	}
