1	const UUID_RE =
2	  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
3	
4	type JsonRecord = Record<string, unknown>;
5	
6	export interface DirectInvoiceAttributionResult {
7	  metadata: JsonRecord;
8	  lineItems?: unknown[];
9	}
10	
11	const ID_ALIASES = {
12	  eventId: ['eventId', 'event_id', 'scheduleEventId', 'schedule_event_id'],
13	  courseId: [
14	    'courseId',
15	    'course_id',
16	    'trainingCourseId',
17	    'training_course_id',
18	    'programId',
19	    'program_id',
20	  ],
21	  classId: ['classId', 'class_id', 'trainingClassId', 'training_class_id'],
22	  courseBalanceId: [
23	    'courseBalanceId',
24	    'course_balance_id',
25	    'studentCourseBalanceId',
26	    'student_course_balance_id',
27	    'hoursAppliedToCourse',
28	  ],
29	  instructorId: ['instructorId', 'instructor_id'],
30	  aircraftId: ['aircraftId', 'aircraft_id', 'equipmentId', 'equipment_id'],
31	} as const;
32	
33	const TEXT_ALIASES = {
34	  courseName: [
35	    'courseName',
36	    'course_name',
37	    'programName',
38	    'program_name',
39	    'trainingCourseName',
40	    'training_course_name',
41	  ],
42	  className: ['className', 'class_name', 'trainingClassName'],
43	  instructorName: ['instructorName', 'instructorLabel', 'instructor_name'],
44	  aircraftLabel: ['aircraftLabel', 'aircraftName', 'tailNumber'],
45	} as const;
46	
47	const DIRECT_ID_KEYS = Object.keys(ID_ALIASES) as Array<
48	  keyof typeof ID_ALIASES
49	>;
50	const DIRECT_TEXT_KEYS = Object.keys(TEXT_ALIASES) as Array<
51	  keyof typeof TEXT_ALIASES
52	>;
53	
54	function isRecord(value: unknown): value is JsonRecord {
55	  return value !== null && typeof value === 'object' && !Array.isArray(value);
56	}
57	
58	function readString(record: JsonRecord, aliases: readonly string[]) {
59	  for (const alias of aliases) {
60	    const value = record[alias];
61	    if (typeof value === 'string' && value.trim()) {
62	      return value.trim();
63	    }
64	  }
65	  return undefined;
66	}
67	
68	function readUuid(record: JsonRecord, aliases: readonly string[]) {
69	  const value = readString(record, aliases);
70	  return value && UUID_RE.test(value) ? value : undefined;
71	}
72	
73	function collectDirectAttribution(record: JsonRecord) {
74	  const direct: JsonRecord = {};
75	  for (const key of DIRECT_ID_KEYS) {
76	    const value = readUuid(record, ID_ALIASES[key]);
77	    if (value) direct[key] = value;
78	  }
79	  for (const key of DIRECT_TEXT_KEYS) {
80	    const value = readString(record, TEXT_ALIASES[key]);
81	    if (value) direct[key] = value;
82	  }
83	  return direct;
84	}
85	
86	export function extractDirectInvoiceAttribution(value: unknown): JsonRecord {
87	  return isRecord(value) ? collectDirectAttribution(value) : {};
88	}
89	
90	function scrubMalformedIdAliases(record: JsonRecord) {
91	  const next: JsonRecord = {};
92	  for (const [key, value] of Object.entries(record)) {
93	    if (value !== undefined) next[key] = value;
94	  }
95	  for (const key of DIRECT_ID_KEYS) {
96	    for (const alias of ID_ALIASES[key]) {
97	      const value = next[alias];
98	      if (value === undefined) continue;
99	      if (typeof value === 'string' && UUID_RE.test(value.trim())) {
100	        next[alias] = value.trim();
101	        continue;
102	      }
103	      delete next[alias];
104	    }
105	  }
106	  return next;
107	}
108	
109	function hasDirectAttribution(record: JsonRecord) {
110	  return DIRECT_ID_KEYS.some((key) => typeof record[key] === 'string');
111	}
112	
113	function mergeAttribution(
114	  target: JsonRecord,
115	  fallback: JsonRecord,
116	  source: 'direct_invoice_metadata' | 'direct_line_item_metadata',
117	) {
118	  const sanitizedTarget = scrubMalformedIdAliases(target);
119	  const direct = {
120	    ...collectDirectAttribution(fallback),
121	    ...collectDirectAttribution(sanitizedTarget),
122	  };
123	  const next = { ...sanitizedTarget, ...direct };
124	  if (hasDirectAttribution(next)) {
125	    next.attributionSource =
126	      typeof target.attributionSource === 'string'
127	        ? target.attributionSource
128	        : source;
129	    next.attributionSchemaVersion =
130	      typeof target.attributionSchemaVersion === 'number'
131	        ? target.attributionSchemaVersion
132	        : 1;
133	  }
134	  return next;
135	}
136	
137	export function populateDirectInvoiceAttributionIds(input: {
138	  metadata?: JsonRecord | null;
139	  lineItems?: unknown[] | null;
140	}): DirectInvoiceAttributionResult {
141	  const metadata = mergeAttribution(
142	    input.metadata ?? {},
143	    {},
144	    'direct_invoice_metadata',
145	  );
146	
147	  if (!Array.isArray(input.lineItems)) {
148	    return { metadata };
149	  }
150	
151	  return {
152	    metadata,
153	    lineItems: input.lineItems.map((item) =>
154	      isRecord(item)
155	        ? mergeAttribution(item, metadata, 'direct_line_item_metadata')
156	        : item,
157	    ),
158	  };
159	}
