1	export interface InvoiceTaxLine {
2	  quantity?: unknown;
3	  rate?: unknown;
4	  subtotal?: unknown;
5	  amount?: unknown;
6	  taxRate?: unknown;
7	  taxAmount?: unknown;
8	  taxInclusive?: unknown;
9	}
10	
11	export interface InvoiceLineTaxBreakdown {
12	  subtotalBeforeTax: number;
13	  taxAmount: number;
14	  taxRate: number;
15	  taxInclusive: boolean;
16	  total: number;
17	}
18	
19	export interface InvoiceTaxSummary {
20	  hasTax: boolean;
21	  subtotalBeforeTax: number;
22	  taxAmount: number;
23	  total: number;
24	}
25	
26	function finiteNumber(value: unknown, fallback = 0): number {
27	  const parsed = Number(value);
28	  return Number.isFinite(parsed) ? parsed : fallback;
29	}
30	
31	function roundMoney(value: number): number {
32	  return Math.round(value * 100) / 100;
33	}
34	
35	/**
36	 * Returns the persisted tax snapshot for an invoice line in display-ready
37	 * dollar amounts. Tax-inclusive lines expose their pre-tax subtotal so the
38	 * invoice summary still reconciles as subtotal + tax = total.
39	 */
40	export function getInvoiceLineTaxBreakdown(
41	  line: InvoiceTaxLine,
42	): InvoiceLineTaxBreakdown {
43	  const quantity = finiteNumber(line.quantity);
44	  const rate = finiteNumber(line.rate);
45	  const taxAmount = Math.max(0, roundMoney(finiteNumber(line.taxAmount)));
46	  const taxRate = Math.max(0, finiteNumber(line.taxRate));
47	  const taxInclusive = line.taxInclusive === true;
48	  const fallbackSubtotal = roundMoney(quantity * rate);
49	  const listedSubtotal =
50	    line.subtotal === null || line.subtotal === undefined
51	      ? fallbackSubtotal
52	      : roundMoney(finiteNumber(line.subtotal, fallbackSubtotal));
53	  const fallbackTotal = taxInclusive
54	    ? listedSubtotal
55	    : roundMoney(listedSubtotal + taxAmount);
56	  const total =
57	    line.amount === null || line.amount === undefined
58	      ? fallbackTotal
59	      : roundMoney(finiteNumber(line.amount, fallbackTotal));
60	
61	  return {
62	    subtotalBeforeTax: roundMoney(
63	      taxInclusive ? Math.max(0, listedSubtotal - taxAmount) : listedSubtotal,
64	    ),
65	    taxAmount,
66	    taxRate,
67	    taxInclusive,
68	    total,
69	  };
70	}
71	
72	export function summarizeInvoiceTaxes(
73	  lines: readonly InvoiceTaxLine[],
74	  invoiceTotal?: unknown,
75	): InvoiceTaxSummary {
76	  const breakdowns = lines.map(getInvoiceLineTaxBreakdown);
77	  const taxAmount = roundMoney(
78	    breakdowns.reduce((sum, line) => sum + line.taxAmount, 0),
79	  );
80	  const lineTotal = roundMoney(
81	    breakdowns.reduce((sum, line) => sum + line.total, 0),
82	  );
83	  const parsedInvoiceTotal = Number(invoiceTotal);
84	  const total = Number.isFinite(parsedInvoiceTotal)
85	    ? roundMoney(parsedInvoiceTotal)
86	    : lineTotal;
87	
88	  return {
89	    hasTax: taxAmount > 0,
90	    subtotalBeforeTax: roundMoney(Math.max(0, total - taxAmount)),
91	    taxAmount,
92	    total,
93	  };
94	}
95	
96	export function formatInvoiceTaxRate(rate: unknown): string {
97	  const parsed = Math.max(0, finiteNumber(rate));
98	  return new Intl.NumberFormat('en-US', {
99	    maximumFractionDigits: 4,
100	  }).format(parsed);
101	}
102

1	export const LOCATION_TAX_REFERENCE_AMOUNT_CENTS = 10_000;
