89	export function formatLocationTaxAddress(address: LocationTaxAddress): string {
90	  return [
91	    address.line1,
92	    [address.city, address.state, address.postalCode]
93	      .filter(Boolean)
94	      .join(', ')
95	      .replace(`, ${address.postalCode}`, ` ${address.postalCode}`),
