102	function parsePercentage(value: string | null | undefined): number | null {
103	  if (typeof value !== 'string' || value.trim() === '') return null;
104	  const parsed = Number(value);
105	  return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
106	}
