108	/**
109	 * Stripe's calculation-level breakdown contains the combined percentage used
110	 * for the transaction. The expanded line item adds the named state/county/city
111	 * jurisdictions that make up that total.
112	 */
113	export function summarizeStripeLocationTaxRate({
114	  calculationBreakdown,
115	  lineItemBreakdown,
116	}: {
117	  calculationBreakdown: StripeTaxBreakdownLike[];
118	  lineItemBreakdown: StripeTaxBreakdownLike[];
119	}): StripeLocationTaxSummary {
120	  const calculationRates = calculationBreakdown
121	    .filter(
122	      (item) =>
123	        item.tax_rate_details?.rate_type !== 'flat_amount' &&
124	        item.tax_rate_details?.tax_type !== 'retail_delivery_fee',
125	    )
126	    .map((item) => parsePercentage(item.tax_rate_details?.percentage_decimal))
127	    .filter((rate): rate is number => rate !== null);
128	
129	  const jurisdictionRates = lineItemBreakdown
130	    .map((item) => {
131	      const rate = parsePercentage(item.tax_rate_details?.percentage_decimal);
132	      if (rate === null || !item.tax_rate_details) return null;
133	      return {
134	        name:
135	          item.jurisdiction?.display_name ??
136	          item.tax_rate_details.display_name ??
137	          'Sales tax',
138	        level: item.jurisdiction?.level ?? 'jurisdiction',
139	        rate,
140	        taxType: item.tax_rate_details.tax_type ?? 'sales_tax',
141	      };
142	    })
143	    .filter(
144	      (jurisdiction): jurisdiction is LocationTaxJurisdiction =>
145	        jurisdiction !== null,
146	    );
147	
148	  const rateParts =
149	    calculationRates.length > 0
150	      ? calculationRates
151	      : jurisdictionRates.map((jurisdiction) => jurisdiction.rate);
152	  const hasExplicitZeroRate =
153	    rateParts.length > 0 && rateParts.every((rate) => rate === 0);
154	  const rate =
155	    rateParts.length > 0
156	      ? Number(
157	          rateParts.reduce((total, current) => total + current, 0).toFixed(5),
158	        )
159	      : hasExplicitZeroRate
160	        ? 0
161	        : null;
162	
163	  const taxabilityReasons = [...calculationBreakdown, ...lineItemBreakdown]
164	    .map((item) => item.taxability_reason)
165	    .filter(
166	      (reason, index, all): reason is string =>
167	        typeof reason === 'string' && all.indexOf(reason) === index,
168	    );
169	
170	  return { rate, jurisdictions: jurisdictionRates, taxabilityReasons };
171	}
