65	function computeCanonicalBalanceCents(
66	  invoiceRows: Array<{
67	    id?: string;
68	    amount: number;
69	    status: string;
70	    metadata: unknown;
71	    balanceImpactCents: number;
72	  }>,
73	  paymentRows: Array<{
74	    amount: number;
75	    status: string;
76	    balanceDelta: number | null;
77	    invoiceId?: string | null;
78	  }>,
79	): number {
80	  const prepaidInvoicesById = new Map(
81	    invoiceRows
82	      .filter(
83	        (invoice) =>
84	          typeof invoice.id === 'string' &&
85	          isPrepaidTrainingPurchaseMetadata(invoice.metadata),
86	      )
87	      .map((invoice) => [invoice.id as string, invoice]),
88	  );
89	  const invoiceBalance = invoiceRows.reduce((sum, invoice) => {
90	    const meta = invoiceMetaRecord(invoice.metadata);
91	    if (meta.archived || isPrepaidTrainingPurchaseMetadata(meta)) return sum;
92	    if (
93	      CANONICAL_BALANCE_EXCLUDED_STATUSES.has(
94	        String(invoice.status ?? '').toLowerCase(),
95	      )
96	    ) {
97	      return sum;
98	    }
99	
100	    const metaType = typeof meta.type === 'string' ? meta.type : undefined;
101	    const isCredit =
102	      metaType === 'Credit' || metaType === 'Refund'
103	        ? true
104	        : metaType === 'Debit'
105	          ? false
106	          : invoice.balanceImpactCents > 0;
107	    return isCredit ? sum + invoice.amount : sum - invoice.amount;
108	  }, 0);
109	
110	  const paymentBalance = paymentRows.reduce((sum, payment) => {
111	    const prepaidInvoice =
112	      typeof payment.invoiceId === 'string'
113	        ? prepaidInvoicesById.get(payment.invoiceId)
114	        : undefined;
115	    if (prepaidInvoice) {
116	      return String(payment.status ?? '').toLowerCase() === 'completed'
117	        ? sum +
118	            getPrepaidTrainingCreditCents(
119	              prepaidInvoice.metadata,
120	              prepaidInvoice.amount,
121	            )
122	        : sum;
123	    }
124	    if (
125	      payment.balanceDelta !== null &&
126	      payment.balanceDelta !== undefined &&
127	      Number.isFinite(payment.balanceDelta)
128	    ) {
129	      return sum + payment.balanceDelta;
130	    }
131	    if (
132	      String(payment.status ?? '').toLowerCase() === 'completed' &&
133	      Number.isFinite(payment.amount)
134	    ) {
135	      return sum + payment.amount;
136	    }
137	    return sum;
138	  }, 0);
139	
140	  return invoiceBalance + paymentBalance;
141	}
