146	  studentId: string;
147	  updatedAt: Date;
148	}): Promise<void> {
149	  if (typeof (db as { update?: unknown }).update !== 'function') return;
150	
151	  const [invoiceRows, paymentRows] = await Promise.all([
152	    db
153	      .select({
154	        id: schema.studentInvoices.id,
155	        amount: schema.studentInvoices.amount,
156	        status: schema.studentInvoices.status,
