164	          eq(schema.studentInvoices.locationId, input.locationId),
165	          eq(schema.studentInvoices.studentId, input.studentId),
166	        ),
167	      ),
168	    db
169	      .select({
170	        amount: schema.studentPaymentHistory.amount,
