230	function getSignOffState(
231	  event: ScheduleSignOffSnapshot | undefined,
232	  meta: Record<string, unknown>,
233	) {
234	  const metaStudentSigned =
235	    typeof meta.studentSignedOff === 'boolean'
236	      ? meta.studentSignedOff
237	      : undefined;
238	  const metaInstructorSigned =
239	    typeof meta.instructorSignedOff === 'boolean'
240	      ? meta.instructorSignedOff
241	      : undefined;
242	  const studentSigned =
243	    event?.studentSignedOff === true || metaStudentSigned === true;
244	  const instructorSigned =
245	    event?.instructorSignedOff === true || metaInstructorSigned === true;
246	  const studentNeedsSignOff =
247	    !studentSigned &&
248	    (metaStudentSigned === false ||
249	      event?.pendingStudentSignoff === true ||
250	      event?.adminCompletedWithoutPins === true ||
251	      (!event && metaStudentSigned !== true));
252	  const instructorNeedsSignOff =
253	    !instructorSigned &&
254	    (metaInstructorSigned === false ||
255	      event?.pendingInstructorSignoff === true);
256	
257	  return {
258	    studentSigned,
259	    instructorSigned,
260	    studentNeedsSignOff,
261	    instructorNeedsSignOff,
262	    signOffStillOpen: studentNeedsSignOff || instructorNeedsSignOff,
263	  };
264	}
