266	export async function getOpenSignOffGate(
267	  orgId: string,
268	  locationId: string,
269	  invoice: InvoiceForSignOffGate,
270	): Promise<BillingSignOffGateDecision> {
271	  const status = String(invoice.status ?? '').toLowerCase();
272	  const meta = invoiceMetaRecord(invoice.metadata);
273	  const eventId = invoiceEventId(meta);
274	  const [event] = eventId
275	    ? await findScheduleSignOffSnapshotsForOrg(orgId, locationId, [eventId])
276	    : [];
277	  const rawDeadline =
278	    event?.signoffDeadline ??
279	    (typeof meta.approvalDeadline === 'string'
280	      ? new Date(meta.approvalDeadline)
281	      : null);
282	  const deadline =
283	    rawDeadline instanceof Date && !Number.isNaN(rawDeadline.getTime())
284	      ? rawDeadline
285	      : rawDeadline;
286	  const signOffState = getSignOffState(event, meta);
287	  const hasSignOffContract =
288	    status === 'pending sign-off' ||
289	    Boolean(event) ||
290	    typeof meta.studentSignedOff === 'boolean' ||
291	    typeof meta.instructorSignedOff === 'boolean' ||
292	    typeof meta.approvalDeadline === 'string';
293	  const signOffRequired =
294	    hasSignOffContract &&
295	    (signOffState.signOffStillOpen || status === 'pending sign-off');
296	
297	  return evaluateBillingSignOffGate({
298	    invoiceStatus: invoice.status,
299	    signOffRequired,
300	    signedOff: signOffRequired && !signOffState.signOffStillOpen,
301	    signoffDeadline: deadline,
302	  });
303	}
