338	export async function revertPrematureSignOffApprovals(
339	  orgId: string,
340	  locationId: string,
341	  invoices: InvoiceForSignOffGate[],
342	): Promise<string[]> {
343	  const candidates = invoices.filter((invoice) => {
344	    if (!isInvoiceApprovedForSchedule(invoice.status)) return false;
345	    if (!invoiceEventId(invoice.metadata)) return false;
346	    const meta = invoiceMetaRecord(invoice.metadata);
347	    return typeof meta.approvedAt === 'string' || invoice.paidAt != null;
348	  });
349	  if (candidates.length === 0) return [];
350	
351	  const eventIds = [
352	    ...new Set(
353	      candidates
354	        .map((invoice) => invoiceEventId(invoice.metadata))
355	        .filter((id): id is string => !!id),
356	    ),
357	  ];
358	  const events = await findScheduleSignOffSnapshotsForOrg(
359	    orgId,
360	    locationId,
361	    eventIds,
362	  );
363	  const eventMap = new Map(events.map((event) => [event.id, event]));
364	  const reverted: string[] = [];
365	
366	  for (const invoice of candidates) {
367	    const meta = invoiceMetaRecord(invoice.metadata);
368	    const eventId = invoiceEventId(meta);
369	    if (!eventId) continue;
370	    const event = eventMap.get(eventId);
371	    const deadline =
372	      event?.signoffDeadline ??
373	      (typeof meta.approvalDeadline === 'string'
374	        ? new Date(meta.approvalDeadline)
375	        : null);
376	    const gate = evaluateBillingSignOffGate({
377	      invoiceStatus: 'Pending Sign-Off',
378	      signOffRequired: true,
379	      signedOff: isSignOffComplete(event, meta),
380	      signoffDeadline: deadline,
381	    });
382	    const signOffState = getSignOffState(event, meta);
383	
384	    if (!gate.blocked || !signOffState.signOffStillOpen) continue;
385	
386	    const nextMeta: Record<string, unknown> = {
387	      ...meta,
388	      pendingBalanceImpact: pendingSignOffBalanceImpact(invoice),
389	      autoBilled: false,
390	    };
391	    nextMeta.approvedAt = undefined;
392	    nextMeta.approvedBy = undefined;
393	
394	    await removeInvoiceSettlementLinks(orgId, invoice.id);
395	    await mvpRepository.studentInvoices.updateWithBalanceAdjust(
396	      orgId,
397	      invoice.id,
398	      invoice.studentId,
399	      {
400	        status: invoice.status,
401	        amount: invoice.amount,
402	        balanceImpactCents: invoice.balanceImpactCents,
403	      },
404	      {
405	        status: 'Pending Sign-Off',
406	        paidAt: null,
407	        balanceImpact: 0,
408	        metadata: nextMeta,
409	      },
410	    );
411	    await db
412	      .update(schema.scheduleEvents)
413	      .set({
414	        pendingStudentSignoff: signOffState.studentNeedsSignOff,
415	        pendingInstructorSignoff: signOffState.instructorNeedsSignOff,
416	        studentSignedOff: signOffState.studentSigned,
417	        instructorSignedOff: signOffState.instructorSigned,
418	        adminCompletedWithoutPins: false,
419	        updatedAt: new Date(),
420	      })
421	      .where(
422	        and(
423	          eq(schema.scheduleEvents.id, eventId),
424	          eq(schema.scheduleEvents.flightSchoolId, orgId),
425	          eq(schema.scheduleEvents.locationId, locationId),
426	        ),
427	      );
428	    reverted.push(invoice.id);
429	  }
430	
431	  return reverted;
432	}
