593	      createdAt: schema.studentInvoices.createdAt,
594	    })
595	    .from(schema.studentInvoices)
596	    .where(
597	      and(
598	        eq(schema.studentInvoices.flightSchoolId, orgId),
599	        eq(schema.studentInvoices.locationId, locationId),
600	        eq(schema.studentInvoices.studentId, studentId),
