610	  const [rawPaymentRows, rawInvoiceRows] = await Promise.all([
611	    paymentRowsPromise,
612	    invoiceRowsPromise,
613	  ]);
614	  const paymentRows = (Array.isArray(rawPaymentRows) ? rawPaymentRows : []).map(
615	    (row) => {
616	      const payment = (row ?? {}) as Record<string, unknown>;
617	      return {
618	        invoiceId:
619	          typeof payment.invoiceId === 'string' ? payment.invoiceId : null,
620	        amount:
621	          typeof payment.amount === 'number' && Number.isFinite(payment.amount)
622	            ? payment.amount
623	            : 0,
624	        balanceDelta:
625	          typeof payment.balanceDelta === 'number' &&
