635	    Array.isArray(rawInvoiceRows) ? rawInvoiceRows : []
636	  )
637	    .map((row) => {
638	      const invoice = (row ?? {}) as Record<string, unknown>;
639	      return {
640	        id: typeof invoice.id === 'string' ? invoice.id : '',
641	        amount:
642	          typeof invoice.amount === 'number' && Number.isFinite(invoice.amount)
