818	    });
819	    await db
820	      .update(schema.studentInvoices)
821	      .set({ paidAt: now, updatedAt: now })
822	      .where(
823	        and(
824	          eq(schema.studentInvoices.id, invoice.id),
825	          eq(schema.studentInvoices.flightSchoolId, orgId),
826	          eq(schema.studentInvoices.locationId, locationId),
827	          eq(schema.studentInvoices.studentId, studentId),
828	        ),
829	      );
830	    result.externallySettledCents += remaining;
831	    result.invoicesSettled++;
832	  }
833	
834	  for (const invoice of invoiceRows) {
835	    if (prepaidPurchaseInvoiceIds.has(invoice.id)) continue;
836	    if (invoice.manuallyMarkedPaid) continue;
837	    if (!isBalanceImpactingSettlementStatus(invoice.status)) continue;
838	    if (!isDebitInvoiceForSettlement(invoice)) continue;
839	    if (isFspPaidImport(invoice)) continue;
840	
841	    const existingPayments = paymentsByInvoice.get(invoice.id) ?? [];
842	    const existingPaid = existingPayments.reduce(
843	      (sum, payment) => sum + paidAmountForInvoice(payment),
