851	        ),
852	      );
853	      if (remaining <= 0 || !hasLocalBalanceAllocation) continue;
854	    }
855	
856	    if (remaining <= 0) {
857	      await db
858	        .update(schema.studentInvoices)
859	        .set({
860	          status: 'Completed',
861	          paidAt: now,
862	          updatedAt: now,
863	        })
864	        .where(
865	          and(
866	            eq(schema.studentInvoices.id, invoice.id),
867	            eq(schema.studentInvoices.flightSchoolId, orgId),
868	            eq(schema.studentInvoices.locationId, locationId),
869	            eq(schema.studentInvoices.studentId, studentId),
870	          ),
871	        );
