878	        await db
879	          .update(schema.studentInvoices)
880	          .set({ status: 'Partially Paid', paidAt: null, updatedAt: now })
881	          .where(
882	            and(
883	              eq(schema.studentInvoices.id, invoice.id),
884	              eq(schema.studentInvoices.flightSchoolId, orgId),
885	              eq(schema.studentInvoices.locationId, locationId),
886	              eq(schema.studentInvoices.studentId, studentId),
887	            ),
888	          );
889	        result.invoicesPartiallySettled++;
890	      }
891	      continue;
892	    }
893	
894	    const applied = Math.min(availableLocalCents, remaining);
895	    await insertInvoiceSettlementPayment({
896	      orgId,
897	      locationId,
898	      studentId,
899	      invoiceId: invoice.id,
900	      amountCents: applied,
901	      description: 'Account Balance Applied',
902	      paymentMethod: 'Account Balance',
903	      reference: `${LOCAL_BALANCE_ALLOCATION_REFERENCE_PREFIX}${invoice.id}`,
904	      paymentDate: now,
905	      trainingPlanBalanceId: trainingPlanBalanceIdForInvoice(invoice),
