918	          eq(schema.studentInvoices.id, invoice.id),
919	          eq(schema.studentInvoices.flightSchoolId, orgId),
920	          eq(schema.studentInvoices.locationId, locationId),
921	          eq(schema.studentInvoices.studentId, studentId),
922	        ),
