953	  }
954	
955	  const unpaid = await db
956	    .select({
957	      id: schema.studentInvoices.id,
958	      amount: schema.studentInvoices.amount,
959	      balanceImpactCents: schema.studentInvoices.balanceImpactCents,
960	      metadata: schema.studentInvoices.metadata,
961	    })
962	    .from(schema.studentInvoices)
963	    .where(
964	      and(
965	        eq(schema.studentInvoices.flightSchoolId, orgId),
966	        eq(schema.studentInvoices.locationId, locationId),
