103	function lineItemAmountCents(item: InvoiceProcessingFeeLineItem) {
104	  if (typeof item.amount === 'number' && Number.isFinite(item.amount)) {
105	    return Math.round(item.amount * 100);
106	  }
107	
108	  const quantity =
109	    typeof item.quantity === 'number' && Number.isFinite(item.quantity)
110	      ? item.quantity
111	      : 1;
112	  const rate =
113	    typeof item.rate === 'number' && Number.isFinite(item.rate) ? item.rate : 0;
