118	function toNonNegativeNumber(value: unknown) {
119	  const numeric =
120	    typeof value === 'number'
121	      ? value
122	      : typeof value === 'string' && value.trim() !== ''
123	        ? Number(value)
124	        : 0;
125	  return Number.isFinite(numeric) && numeric > 0 ? numeric : 0;
126	}
