138	export function calculateProcessingFeeCents({
139	  subtotalCents,
140	  feeType,
141	  feeValue,
142	}: {
143	  subtotalCents: number;
144	  feeType: ProcessingFeeType;
145	  feeValue: number;
146	}) {
147	  const value = Math.max(0, feeValue);
148	  if (value <= 0) return 0;
149	  if (feeType === 'percentage') {
150	    return Math.round(subtotalCents * (value / 100));
151	  }
152	  return Math.round(value * 100);
