171	export function buildInvoiceLineItemsWithProcessingFee({
172	  lineItems,
173	  invoiceAmountCents,
174	  settings,
175	  paymentMethodType,
176	  feeBaseCents,
177	}: {
178	  lineItems: InvoiceProcessingFeeLineItem[] | null | undefined;
179	  invoiceAmountCents: number;
180	  settings: ProcessingFeeSettings | null | undefined;
181	  paymentMethodType: string;
182	  feeBaseCents?: number;
183	}) {
184	  const existingLineItems = Array.isArray(lineItems) ? lineItems : [];
185	  const existingFeeItem = existingLineItems.find(isProcessingFeeLineItem);
186	  const baseLineItems = existingLineItems.filter(
187	    (item) => !isProcessingFeeLineItem(item),
188	  );
189	  const previousFeeCents = existingFeeItem
190	    ? lineItemAmountCents(existingFeeItem)
191	    : 0;
192	  const subtotalCents = Math.max(0, invoiceAmountCents - previousFeeCents);
193	  const feeSubtotalCents =
194	    typeof feeBaseCents === 'number' && Number.isFinite(feeBaseCents)
195	      ? Math.max(0, feeBaseCents)
196	      : subtotalCents;
197	  const cardProcessingFeeType = normalizeProcessingFeeType(
198	    settings?.cardProcessingFeeType,
199	  );
200	  const cardProcessingFeeValue =
201	    settings?.cardProcessingFeeValue == null
202	      ? toNonNegativeNumber(settings?.processingFeePercent)
203	      : toNonNegativeNumber(settings.cardProcessingFeeValue);
204	  const achProcessingFeeType = normalizeAchProcessingFeeType(
205	    settings?.achProcessingFeeType,
206	  );
207	  const achProcessingFeeValue = toNonNegativeNumber(
208	    settings?.achProcessingFeeValue,
209	  );
210	  const isCard = paymentMethodType === 'card';
211	  const isAch = paymentMethodType === 'us_bank_account';
212	  const processingFeeCents = isCard
213	    ? calculateProcessingFeeCents({
214	        subtotalCents: feeSubtotalCents,
215	        feeType: cardProcessingFeeType,
216	        feeValue: cardProcessingFeeValue,
217	      })
218	    : isAch
219	      ? calculateAchProcessingFeeCents({
220	          subtotalCents: feeSubtotalCents,
221	          achProcessingFeeType,
222	          achProcessingFeeValue,
223	        })
224	      : 0;
225	
226	  const feeLineItem: InvoiceProcessingFeeLineItem | null =
227	    processingFeeCents > 0
228	      ? {
229	          id: isAch
230	            ? ACH_PROCESSING_FEE_LINE_ITEM_ID
231	            : CREDIT_CARD_PROCESSING_FEE_LINE_ITEM_ID,
232	          description: isAch
233	            ? ACH_PROCESSING_FEE_LABEL
234	            : CREDIT_CARD_PROCESSING_FEE_LABEL,
235	          quantity: 1,
236	          rate: processingFeeCents / 100,
237	          amount: processingFeeCents / 100,
238	          isCustom: true,
239	          // 242202 G3: processing fees are categorically a service fee.
240	          category: 'service_fee',
241	        }
242	      : null;
243	
244	  return {
245	    lineItems: feeLineItem ? [...baseLineItems, feeLineItem] : baseLineItems,
246	    subtotalCents,
247	    processingFeeCents,
248	    totalCents: subtotalCents + processingFeeCents,
249	  };
250	}
