30	export interface TrainingPlanLineTaxBreakdown {
31	  subtotal: number;
32	  taxAmount: number;
33	  total: number;
34	  taxCategory: string;
35	  taxRate: number;
36	  taxInclusive: boolean;
37	  applied: boolean;
