39	
40	export const NO_TRAINING_PLAN_TAX_SETTINGS: TrainingPlanTaxSettings = {
41	  enabled: false,
42	  locationTaxRate: 0,
43	  taxInclusive: false,
44	  categories: [
45	    {
46	      id: 'non_taxable',
47	      label: 'No tax',
48	      description: 'Tax is not applied to this line.',
49	      rate: 0,
50	      active: true,
51	      calculationBasis: 'manual',
52	    },
53	  ],
