55	
56	function isRecord(value: unknown): value is Record<string, unknown> {
57	  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
58	}
59	
60	function nonNegativeNumber(value: unknown): number {
61	  const parsed =
62	    typeof value === 'number'
63	      ? value
64	      : typeof value === 'string' && value.trim()
65	        ? Number(value)
66	        : 0;
67	  return Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
68	}
69	
70	function roundMoney(value: number): number {
71	  return Math.round((value + Number.EPSILON) * 100) / 100;
72	}
73	
74	function normalizeCalculationBasis(
75	  value: unknown,
76	): TrainingPlanTaxCategory['calculationBasis'] {
77	  return value === 'customer_address' ||
78	    value === 'training_location' ||
79	    value === 'manual'
80	    ? value
81	    : 'business_location';
82	}
83	
84	export function normalizeTrainingPlanTaxSettings(
85	  value: unknown,
86	): TrainingPlanTaxSettings {
87	  if (!isRecord(value)) return NO_TRAINING_PLAN_TAX_SETTINGS;
88	
89	  const locationTaxRate = nonNegativeNumber(value.locationTaxRate);
90	  const seen = new Set<string>();
91	  const categories = (Array.isArray(value.categories) ? value.categories : [])
92	    .map((category): TrainingPlanTaxCategory | null => {
93	      if (!isRecord(category)) return null;
94	      const id = typeof category.id === 'string' ? category.id.trim() : '';
95	      if (!id || seen.has(id)) return null;
96	      seen.add(id);
97	      const calculationBasis = normalizeCalculationBasis(
98	        category.calculationBasis,
99	      );
100	      const configuredRate = nonNegativeNumber(category.rate);
101	      const rate =
102	        configuredRate > 0 ||
103	        id === 'non_taxable' ||
104	        calculationBasis === 'manual'
105	          ? configuredRate
106	          : locationTaxRate;
107	      return {
108	        id,
109	        label:
110	          typeof category.label === 'string' && category.label.trim()
111	            ? category.label.trim()
112	            : id === 'non_taxable'
113	              ? 'No tax'
114	              : 'Tax rule',
115	        description:
116	          typeof category.description === 'string'
117	            ? category.description.trim()
118	            : undefined,
119	        rate,
120	        active: typeof category.active === 'boolean' ? category.active : true,
121	        calculationBasis,
122	      };
123	    })
124	    .filter(
125	      (category): category is TrainingPlanTaxCategory => category !== null,
126	    );
127	
128	  if (!seen.has('non_taxable')) {
129	    categories.unshift(NO_TRAINING_PLAN_TAX_SETTINGS.categories[0]);
130	  }
131	
132	  return {
133	    enabled: value.enabled === true,
134	    locationTaxRate,
135	    taxInclusive: value.taxInclusive === true,
136	    categories,
137	  };
138	}
139	
140	export function getTrainingPlanTaxCategory(
141	  settings: TrainingPlanTaxSettings,
142	  taxCategory: string | null | undefined,
143	): TrainingPlanTaxCategory | null {
144	  const id = taxCategory?.trim();
145	  if (!id) return null;
146	  return settings.categories.find((category) => category.id === id) ?? null;
147	}
148	
149	export function getTrainingPlanTaxRate(
150	  settings: TrainingPlanTaxSettings,
151	  taxCategory: string | null | undefined,
152	): number {
153	  if (!taxCategory || taxCategory === 'non_taxable') return 0;
154	  const category = getTrainingPlanTaxCategory(settings, taxCategory);
155	  if (!category || category.active === false) return 0;
156	  if (category.rate > 0) return category.rate;
157	  if (
158	    category.calculationBasis &&
159	    category.calculationBasis !== 'manual' &&
160	    settings.locationTaxRate > 0
161	  ) {
162	    return settings.locationTaxRate;
163	  }
164	  return 0;
165	}
166	
167	export function formatTrainingPlanTaxRate(
168	  value: number | null | undefined,
169	): string {
170	  const rate = Number(value);
171	  if (!Number.isFinite(rate)) return '0';
172	  return rate.toFixed(5).replace(/\.?0+$/, '') || '0';
173	}
174	
175	/**
176	 * Calculates tax in cents-safe dollar precision. When rates are tax-inclusive,
177	 * `total` remains the listed subtotal and `taxAmount` reports the tax portion.
178	 */
179	export function calculateTrainingPlanLineTax(
180	  input: TrainingPlanLineTaxInput,
181	  settings?: TrainingPlanTaxSettings | null,
182	): TrainingPlanLineTaxBreakdown {
183	  const subtotal = roundMoney(Math.max(0, nonNegativeNumber(input.subtotal)));
184	  const taxCategory = input.taxCategory?.trim() || 'non_taxable';
185	  const resolvedSettings = settings
186	    ? normalizeTrainingPlanTaxSettings(settings)
187	    : null;
188	  const taxRate = resolvedSettings
189	    ? getTrainingPlanTaxRate(resolvedSettings, taxCategory)
190	    : taxCategory === 'non_taxable'
191	      ? 0
192	      : nonNegativeNumber(input.taxRate);
193	  const taxInclusive = resolvedSettings
194	    ? resolvedSettings.taxInclusive
195	    : input.taxInclusive === true;
196	  const enabled = resolvedSettings ? resolvedSettings.enabled : true;
197	  const applied =
198	    enabled && taxCategory !== 'non_taxable' && taxRate > 0 && subtotal > 0;
199	
200	  if (!applied) {
201	    return {
202	      subtotal,
203	      taxAmount: 0,
204	      total: subtotal,
205	      taxCategory,
206	      taxRate,
207	      taxInclusive,
208	      applied: false,
209	    };
210	  }
211	
212	  const taxDecimal = taxRate / 100;
213	  const taxAmount = taxInclusive
214	    ? roundMoney(subtotal - subtotal / (1 + taxDecimal))
215	    : roundMoney(subtotal * taxDecimal);
216	
217	  return {
218	    subtotal,
219	    taxAmount,
220	    total: taxInclusive ? subtotal : roundMoney(subtotal + taxAmount),
221	    taxCategory,
222	    taxRate,
223	    taxInclusive,
224	    applied: true,
225	  };
226	}
