149	  exceptions: StudentProductRateException[],
150	  productId: string,
151	  eventDate?: string | null,
152	): StudentProductRateResolution {
153	  const normalizedProductId = productId.trim();
154	  const effectiveDate =
155	    normalizeIsoDate(eventDate) || new Date().toISOString().slice(0, 10);
156	  const matches = exceptions
157	    .filter((exception) => {
158	      const status = exception.status?.trim().toLowerCase() || 'active';
159	      const effectiveFrom = normalizeIsoDate(exception.effectiveFrom);
160	      const effectiveTo = normalizeIsoDate(exception.effectiveTo);
161	      return (
162	        status === 'active' &&
163	        exception.productId.trim() === normalizedProductId &&
164	        Boolean(effectiveFrom) &&
165	        effectiveFrom <= effectiveDate &&
166	        (!effectiveTo || effectiveTo >= effectiveDate) &&
167	        parseNonNegativeRate(exception.rate) !== null
168	      );
169	    })
170	    .sort((a, b) => {
171	      const byEffectiveDate = b.effectiveFrom.localeCompare(a.effectiveFrom);
172	      if (byEffectiveDate !== 0) return byEffectiveDate;
173	      return normalizeIsoDate(b.createdAt).localeCompare(
174	        normalizeIsoDate(a.createdAt),
175	      );
176	    });
177	  const match = matches[0];
178	  if (!match) {
179	    return { status: 'not_configured', productId: normalizedProductId };
180	  }
181	  return {
182	    status: 'matched',
183	    productId: normalizedProductId,
184	    rate: parseNonNegativeRate(match.rate) as number,
185	    exceptionId: match.id,
186	    productNameSnapshot: match.productNameSnapshot,
187	    effectiveFrom: match.effectiveFrom,
188	    effectiveTo: match.effectiveTo,
189	  };
190	}
191	
192	/**
193	 * Server-side repricing for newly generated automatic invoice lines.
194	 * Program quote pricing runs after this function and therefore retains
195	 * precedence over a standalone product exception.
196	 */
197	export function applyStudentProductRateExceptionsToStoredInvoiceLines(
198	  lines: StudentProductExceptionStoredInvoiceLine[],
199	  exceptions: StudentProductRateException[],
200	  options: { eventDate?: string | null } = {},
201	): {
202	  lines: StudentProductExceptionStoredInvoiceLine[];
203	  appliedCount: number;
204	  total: number;
205	} {
206	  let appliedCount = 0;
207	  const resolvedLines = lines.map((line) => {
208	    if (line.isAuto !== true || hasManualStoredRateAdjustment(line)) {
209	      return line;
210	    }
211	    const productId =
212	      line.productId?.trim() || line.lineItemTypeId?.trim() || '';
213	    if (!productId) return line;
214	    const resolution = resolveStudentProductRateException(
215	      exceptions,
216	      productId,
217	      options.eventDate,
218	    );
219	    if (resolution.status !== 'matched' || resolution.rate === undefined) {
220	      return line;
221	    }
222	
223	    const quantity = Math.max(0, Number(line.quantity ?? line.qty) || 0);
224	    const divisor = Math.max(
225	      1,
226	      Math.trunc(Number(line.groupShareDivisor) || 1),
227	    );
228	    const shareIndex = Math.max(
229	      0,
230	      Math.trunc(Number(line.groupShareIndex) || 0),
231	    );
232	    const fullSubtotal = roundCurrency(quantity * resolution.rate);
233	    const taxRate = Math.max(0, Number(line.taxRate) || 0);
234	    const taxable =
235	      Boolean(line.taxCategoryId) &&
236	      line.taxCategoryId !== 'non_taxable' &&
237	      taxRate > 0 &&
238	      fullSubtotal > 0;
239	    const fullTaxAmount = taxable
240	      ? line.taxInclusive
241	        ? roundCurrency(fullSubtotal - fullSubtotal / (1 + taxRate / 100))
242	        : roundCurrency(fullSubtotal * (taxRate / 100))
243	      : 0;
244	    const subtotal = allocateCurrencyShare(fullSubtotal, divisor, shareIndex);
245	    const taxAmount = allocateCurrencyShare(fullTaxAmount, divisor, shareIndex);
246	    const amount =
247	      line.taxInclusive === true
248	        ? subtotal
249	        : roundCurrency(subtotal + taxAmount);
250	    const appliedRate = allocateCurrencyShare(
251	      resolution.rate,
252	      divisor,
253	      shareIndex,
254	    );
255	    appliedCount += 1;
256	    return {
257	      ...line,
258	      productId,
259	      rate: appliedRate,
260	      subtotal,
261	      taxAmount,
262	      amount,
263	      total: amount,
264	      studentProductRateExceptionId: resolution.exceptionId,
265	      studentProductRateEffectiveFrom: resolution.effectiveFrom,
266	      studentProductRateEffectiveTo: resolution.effectiveTo,
267	      productNameSnapshot: resolution.productNameSnapshot,
268	      quotedRate: resolution.rate,
269	      appliedRate,
270	      rateSource: STUDENT_PRODUCT_EXCEPTION_RATE_SOURCE,
271	      seedRate: appliedRate,
272	      manualRateOverride: false,
273	    };
274	  });
275	
276	  return {
277	    lines: resolvedLines,
278	    appliedCount,
279	    total: roundCurrency(
280	      resolvedLines.reduce(
281	        (sum, line) => sum + (Number(line.amount ?? line.total) || 0),
282	        0,
283	      ),
284	    ),
285	  };
286	}
