4	export function prepaidTrainingPurchaseMetadata(
5	  value: unknown,
6	): Record<string, unknown> {
7	  return value && typeof value === 'object' && !Array.isArray(value)
8	    ? (value as Record<string, unknown>)
9	    : {};
10	}
11	
12	export function isPrepaidTrainingPurchaseMetadata(value: unknown): boolean {
13	  const metadata = prepaidTrainingPurchaseMetadata(value);
14	  return (
15	    metadata.prepaidTrainingPurchase === true ||
16	    metadata.source === PREPAID_TRAINING_PURCHASE_SOURCE
17	  );
18	}
19	
20	export function getPrepaidTrainingCreditCents(
21	  value: unknown,
22	  fallbackCents = 0,
23	): number {
24	  const metadata = prepaidTrainingPurchaseMetadata(value);
25	  const explicitCents = Number(metadata.trainingFundsCreditedCents);
26	  if (Number.isFinite(explicitCents) && explicitCents >= 0) {
27	    return Math.round(explicitCents);
28	  }
29	
30	  const additionalAmount = Number(metadata.additionalAmount);
31	  if (Number.isFinite(additionalAmount) && additionalAmount >= 0) {
32	    return Math.round(additionalAmount * 100);
33	  }
34	
35	  return Math.max(0, Math.round(fallbackCents));
36	}
37	
38	export function getPrepaidAccountBalanceSettlementCents(
39	  value: unknown,
40	): number {
41	  const metadata = prepaidTrainingPurchaseMetadata(value);
42	  const explicitCents = Number(metadata.accountBalanceSettlementCents);
43	  return Number.isFinite(explicitCents) && explicitCents >= 0
44	    ? Math.round(explicitCents)
45	    : 0;
46	}
47	
48	export function getPrepaidPurchaseBalanceCreditCents(
49	  value: unknown,
50	  fallbackCents = 0,
51	): number {
52	  return (
53	    getPrepaidTrainingCreditCents(value, fallbackCents) +
54	    getPrepaidAccountBalanceSettlementCents(value)
55	  );
