57	
58	export function getPrepaidTrainingProcessingFeeCents(
59	  value: unknown,
60	  paymentReceivedCents: number,
61	): number {
62	  const metadata = prepaidTrainingPurchaseMetadata(value);
63	  const explicitCents = Number(metadata.processingFeeCents);
64	  if (Number.isFinite(explicitCents) && explicitCents >= 0) {
65	    return Math.round(explicitCents);
66	  }
67	
68	  return Math.max(
69	    0,
70	    Math.round(paymentReceivedCents) -
71	      getPrepaidPurchaseBalanceCreditCents(metadata),
72	  );
