74	
75	export function getPrepaidTrainingHourPurchase(
76	  value: unknown,
77	  invoiceLineItems?: unknown,
78	): {
79	  hourType: 'flight' | 'ground' | 'simulator' | null;
80	  hours: number;
81	} {
82	  const metadata = prepaidTrainingPurchaseMetadata(value);
83	  const rawHourType =
84	    metadata.purchaseHourType ??
85	    metadata.hourType ??
86	    metadata.purchasedHourType;
87	  const explicitHourType =
88	    rawHourType === 'flight' ||
89	    rawHourType === 'ground' ||
90	    rawHourType === 'simulator'
91	      ? rawHourType
92	      : null;
93	  const hourDelta =
94	    metadata.hourDelta &&
95	    typeof metadata.hourDelta === 'object' &&
96	    !Array.isArray(metadata.hourDelta)
97	      ? (metadata.hourDelta as Record<string, unknown>)
98	      : {};
99	  const inferredDeltaHourType = (
100	    ['flight', 'ground', 'simulator'] as const
101	  ).find((type) => Number(hourDelta[type]) > 0);
102	  const lineItems = Array.isArray(invoiceLineItems)
103	    ? invoiceLineItems.filter(
104	        (item): item is Record<string, unknown> =>
105	          !!item && typeof item === 'object' && !Array.isArray(item),
106	      )
107	    : [];
108	  const inferredLineItem = lineItems.find((item) => {
109	    const rawType = item.type ?? item.bucket;
110	    return (
111	      rawType === 'flight' || rawType === 'ground' || rawType === 'simulator'
112	    );
113	  });
114	  const inferredHourType =
115	    inferredLineItem?.type ?? inferredLineItem?.bucket ?? null;
116	  const hourType =
117	    explicitHourType ??
118	    inferredDeltaHourType ??
119	    (inferredHourType === 'flight' ||
120	    inferredHourType === 'ground' ||
121	    inferredHourType === 'simulator'
122	      ? inferredHourType
123	      : null);
124	  const explicitHours = Number(metadata.hoursPurchased);
125	  const deltaHours = hourType ? Number(hourDelta[hourType]) : 0;
126	  const lineItemHours = Number(inferredLineItem?.quantity);
127	  const hours = Number.isFinite(explicitHours)
128	    ? explicitHours
129	    : Number.isFinite(deltaHours)
130	      ? deltaHours
131	      : Number.isFinite(lineItemHours)
132	        ? lineItemHours
133	        : 0;
134	
135	  return {
136	    hourType,
137	    hours: Math.max(0, hours),
138	  };
139	}
