141	export type PrepaidTrainingBalance = {
142	  trainingPlanBalanceId: string;
143	  courseName: string;
144	  courseAllocationId: string | null;
145	  hourType: 'flight' | 'ground' | 'simulator' | null;
146	  purchasedHours: number;
147	  fundedCents: number;
148	  usedCents: number;
149	  availableCents: number;
150	  availableHours: number;
151	};
152	
153	export function computePrepaidTrainingBalances(
154	  invoices: Array<{
155	    id: string;
156	    amount: number;
157	    metadata?: unknown;
158	  }>,
159	  payments: Array<{
160	    invoiceId?: string | null;
161	    trainingPlanBalanceId?: string | null;
162	    amount: number;
163	    balanceDelta?: number | null;
164	    status?: string | null;
165	    paymentMethod?: string | null;
166	    reference?: string | null;
167	  }>,
168	): PrepaidTrainingBalance[] {
169	  const prepaidInvoicesById = new Map(
170	    invoices
171	      .filter((invoice) => isPrepaidTrainingPurchaseMetadata(invoice.metadata))
172	      .map((invoice) => [invoice.id, invoice]),
173	  );
174	  const balances = new Map<
175	    string,
176	    Omit<PrepaidTrainingBalance, 'availableCents' | 'availableHours'>
177	  >();
178	  const hourBases = new Map<
179	    string,
180	    { allocatedHours: number; valueCents: number }
181	  >();
182	
183	  for (const payment of payments) {
184	    if (
185	      String(payment.status ?? '').toLowerCase() !== 'completed' ||
186	      !payment.invoiceId
187	    ) {
188	      continue;
189	    }
190	    const invoice = prepaidInvoicesById.get(payment.invoiceId);
191	    if (!invoice) continue;
192	    const metadata = prepaidTrainingPurchaseMetadata(invoice.metadata);
193	    const trainingPlanBalanceId =
194	      payment.trainingPlanBalanceId ??
195	      (typeof metadata.trainingPlanBalanceId === 'string'
196	        ? metadata.trainingPlanBalanceId
197	        : null);
198	    if (!trainingPlanBalanceId) continue;
199	    const currentCourseAllocationId =
200	      typeof metadata.currentCourseAllocationId === 'string'
201	        ? metadata.currentCourseAllocationId
202	        : typeof metadata.courseAllocationId === 'string'
203	          ? metadata.courseAllocationId
204	          : null;
205	    const currentCourseName =
206	      typeof metadata.currentCourseName === 'string'
207	        ? metadata.currentCourseName
208	        : typeof metadata.courseName === 'string'
209	          ? metadata.courseName
210	          : 'Training plan';
211	    const hourPurchase = getPrepaidTrainingHourPurchase(metadata);
212	    const current = balances.get(trainingPlanBalanceId) ?? {
213	      trainingPlanBalanceId,
214	      courseName: currentCourseName,
215	      courseAllocationId: currentCourseAllocationId,
216	      hourType: hourPurchase.hourType,
217	      purchasedHours: 0,
218	      fundedCents: 0,
219	      usedCents: 0,
220	    };
221	    if (current.courseAllocationId !== currentCourseAllocationId) {
222	      current.courseName = 'Multiple certificates';
223	      current.courseAllocationId = null;
224	    } else {
225	      current.courseName = currentCourseName;
226	    }
227	    if (current.hourType !== hourPurchase.hourType) {
228	      current.hourType = null;
229	    }
230	    const trainingCreditCents = getPrepaidTrainingCreditCents(
231	      metadata,
232	      invoice.amount,
233	    );
234	    const currentPurchasedHours = Number(metadata.currentPurchasedHours);
235	    const currentPurchasedHourBasisCents = Number(
236	      metadata.currentPurchasedHourBasisCents,
237	    );
238	    const allocatedHours =
239	      Number.isFinite(currentPurchasedHours) && currentPurchasedHours >= 0
240	        ? currentPurchasedHours
241	        : hourPurchase.hours;
242	    const valueCents =
243	      Number.isFinite(currentPurchasedHourBasisCents) &&
244	      currentPurchasedHourBasisCents >= 0
245	        ? Math.round(currentPurchasedHourBasisCents)
246	        : trainingCreditCents;
247	    const hourBasis = hourBases.get(trainingPlanBalanceId) ?? {
248	      allocatedHours: 0,
249	      valueCents: 0,
250	    };
251	    hourBasis.allocatedHours += allocatedHours;
252	    hourBasis.valueCents += valueCents;
253	    hourBases.set(trainingPlanBalanceId, hourBasis);
254	    current.purchasedHours += allocatedHours;
255	    current.fundedCents += trainingCreditCents;
256	    balances.set(trainingPlanBalanceId, current);
257	  }
258	
259	  for (const payment of payments) {
260	    if (
261	      String(payment.status ?? '').toLowerCase() !== 'completed' ||
262	      !payment.trainingPlanBalanceId
263	    ) {
264	      continue;
265	    }
266	    const current = balances.get(payment.trainingPlanBalanceId);
267	    if (!current) continue;
268	    const method = String(payment.paymentMethod ?? '').toLowerCase();
269	    const reference = String(payment.reference ?? '').toLowerCase();
270	    if (
271	      method === 'account balance' ||
272	      reference.startsWith('account-balance-allocation:')
273	    ) {
274	      current.usedCents += Math.max(0, Math.round(payment.amount));
275	    } else if ((payment.balanceDelta ?? 0) < 0) {
276	      current.usedCents += Math.abs(Math.round(payment.balanceDelta ?? 0));
277	    }
278	  }
279	
280	  return [...balances.values()].map((balance) => {
281	    const availableCents = Math.max(0, balance.fundedCents - balance.usedCents);
282	    const hourBasis = hourBases.get(balance.trainingPlanBalanceId);
283	    return {
284	      ...balance,
285	      availableCents,
286	      availableHours:
287	        (hourBasis?.valueCents ?? 0) > 0
288	          ? Math.max(
289	              0,
290	              ((hourBasis?.allocatedHours ?? 0) * availableCents) /
291	                (hourBasis?.valueCents ?? 1),
292	            )
293	          : 0,
294	    };
295	  });
296	}
