97	export function parseFiniteNumber(value: unknown): number | null {
98	  if (value === null || value === undefined || value === '') return null;
99	  const parsed = typeof value === 'number' ? value : Number(value);
100	  return Number.isFinite(parsed) ? parsed : null;
101	}
102	
103	export function roundCurrency(value: number): number {
104	  return Math.round(value * 100) / 100;
105	}
106	
107	export function roundHours(value: number): number {
108	  return Math.round(value * 10) / 10;
109	}
