115	export function isGroundLikeEventType(eventType: unknown): boolean {
116	  if (typeof eventType !== 'string') return false;
117	  const normalized = eventType.trim().toLowerCase();
118	  if (!normalized) return false;
119	  if (normalized.includes('checkride fee')) return false;
120	  return (
121	    normalized.includes('ground') ||
122	    normalized.includes('classroom') ||
123	    normalized.includes('oral')
124	  );
125	}
