127	export function computeScheduledBillableHours(input: {
128	  scheduledHours?: unknown;
129	  startHour?: unknown;
130	  endHour?: unknown;
131	  durationMinutes?: unknown;
132	  startAt?: unknown;
133	  endAt?: unknown;
134	}): number {
135	  const startAt =
136	    typeof input.startAt === 'string' || input.startAt instanceof Date
137	      ? new Date(input.startAt)
138	      : null;
139	  const endAt =
140	    typeof input.endAt === 'string' || input.endAt instanceof Date
141	      ? new Date(input.endAt)
142	      : null;
143	  if (
144	    startAt &&
145	    endAt &&
146	    Number.isFinite(startAt.getTime()) &&
147	    Number.isFinite(endAt.getTime())
148	  ) {
149	    const diffHours = (endAt.getTime() - startAt.getTime()) / 3_600_000;
150	    if (diffHours > 0) return roundHours(diffHours);
151	  }
152	
153	  const scheduledHours = parseFiniteNumber(input.scheduledHours);
154	  if (scheduledHours !== null && scheduledHours > 0) {
155	    return roundHours(scheduledHours);
156	  }
157	
158	  const startHour = parseFiniteNumber(input.startHour);
159	  const endHour = parseFiniteNumber(input.endHour);
160	  if (startHour !== null && endHour !== null) {
161	    let diffHours = endHour - startHour;
162	    if (diffHours < 0) diffHours += 24;
163	    if (diffHours > 0) return roundHours(diffHours);
164	  }
165	
166	  const durationMinutes = parseFiniteNumber(input.durationMinutes);
167	  if (durationMinutes !== null && durationMinutes > 0) {
168	    return roundHours(durationMinutes / 60);
169	  }
170	
171	  return 0;
172	}
173	
174	export function computeGroundBillableHours(input: {
175	  explicitGroundHours?: unknown;
176	  hasAircraft?: boolean;
177	  scheduledHours?: unknown;
178	  startHour?: unknown;
179	  endHour?: unknown;
180	  durationMinutes?: unknown;
181	  startAt?: unknown;
182	  endAt?: unknown;
183	}): number {
184	  const explicitGroundHours = parseFiniteNumber(input.explicitGroundHours);
185	  if (explicitGroundHours !== null && explicitGroundHours > 0) {
186	    return roundHours(explicitGroundHours);
187	  }
188	  if (input.hasAircraft) return 0;
189	  return computeScheduledBillableHours(input);
190	}
191	
192	export function resolveTrainingRate(input: {
193	  eventType: string;
194	  instructorId?: string | null;
195	  locationId?: string | null;
196	  billableQuantity: number;
197	  candidates: RateCandidate[];
198	  allowZeroRate?: boolean;
199	  missingReason?: RateResolutionReason;
200	}): RateResolution {
201	  for (const candidate of input.candidates) {
202	    const parsed = parseFiniteNumber(candidate.value);
203	    const candidateWasPresent =
204	      candidate.value !== null &&
205	      candidate.value !== undefined &&
206	      candidate.value !== '';
207	    if (parsed === null) {
208	      if (candidateWasPresent) {
209	        return {
210	          ok: false,
211	          reason: 'invalid_rate_configuration',
212	          eventType: input.eventType,
213	          instructorId: input.instructorId ?? undefined,
214	          locationId: input.locationId ?? undefined,
215	          billableQuantity: input.billableQuantity,
216	        };
217	      }
218	      continue;
219	    }
220	    if (parsed < 0 || (!input.allowZeroRate && parsed === 0)) {
221	      return {
222	        ok: false,
223	        reason: candidate.presentReason ?? 'invalid_rate_configuration',
224	        eventType: input.eventType,
225	        instructorId: input.instructorId ?? undefined,
226	        locationId: input.locationId ?? undefined,
227	        billableQuantity: input.billableQuantity,
228	      };
229	    }
230	    if (parsed > 0 || input.allowZeroRate) {
231	      return {
232	        ok: true,
233	        rateCents: dollarsToCents(parsed),
234	        rateDollars: roundCurrency(parsed),
235	        source: candidate.source,
236	        billableQuantity: input.billableQuantity,
237	        eventType: input.eventType,
238	        instructorId: input.instructorId ?? undefined,
239	        locationId: input.locationId ?? undefined,
240	      };
241	    }
242	  }
243	
244	  return {
245	    ok: false,
246	    reason: input.missingReason ?? 'missing_instructor_billing_rate',
247	    eventType: input.eventType,
248	    instructorId: input.instructorId ?? undefined,
249	    locationId: input.locationId ?? undefined,
250	    billableQuantity: input.billableQuantity,
251	  };
