254	export function resolveGroundTrainingCharge(
255	  input: GroundTrainingChargeInput,
256	): RateResolution {
257	  const eventType = input.eventType || 'Ground Training';
258	  const instructorId = input.instructorId || undefined;
259	  const locationId = input.locationId || undefined;
260	  const billableQuantity = computeGroundBillableHours(input);
261	
262	  if (!isGroundLikeEventType(eventType) && !input.hasAircraft) {
263	    return {
264	      ok: false,
265	      reason: 'unsupported_event_type',
266	      eventType,
267	      instructorId,
268	      locationId,
269	      billableQuantity,
270	    };
271	  }
272	
273	  if (!instructorId && !input.instructorName) {
274	    return {
275	      ok: false,
276	      reason: 'no_instructor',
277	      eventType,
278	      locationId,
279	      billableQuantity,
280	    };
281	  }
282	
283	  if (billableQuantity <= 0) {
284	    return {
285	      ok: false,
286	      reason: 'no_billable_duration',
287	      eventType,
288	      instructorId,
289	      locationId,
290	      billableQuantity,
291	    };
292	  }
293	
294	  return resolveTrainingRate({
295	    eventType,
296	    instructorId,
297	    locationId,
298	    billableQuantity,
299	    allowZeroRate: input.allowZeroRate,
300	    missingReason: input.locationGroundSchoolRate
301	      ? 'missing_location_ground_school_rate'
302	      : 'missing_instructor_billing_rate',
303	    candidates: [
304	      {
305	        value: input.specificGroundRate,
306	        source: 'student_ground',
307	      },
308	      {
309	        value: input.instructorBillingRate,
310	        source: 'instructor_generic',
311	      },
312	      {
313	        value: input.instructorHourlyRate,
314	        source: 'instructor_hourly',
315	      },
316	      {
