324	export function buildGroundInstructionLine(input: {
325	  resolution: RateResolution;
326	  instructorName?: string | null;
327	  id?: string;
328	}): TrainingInvoiceLine {
329	  const quantity = input.resolution.billableQuantity ?? 0;
330	  let rate = 0;
331	  let rateSource: RateResolutionSource | undefined;
332	  if (isResolvedRate(input.resolution)) {
333	    rate = input.resolution.rateDollars;
334	    rateSource = input.resolution.source;
335	  }
336	  const amount = rateSource ? roundCurrency(quantity * rate) : 0;
337	  return {
338	    id: input.id ?? 'auto-ground',
339	    description: `Ground Instruction: ${input.instructorName || 'Instructor'} — ${quantity} hrs`,
340	    quantity,
341	    rate,
342	    amount,
343	    type: 'ground_instruction',
344	    // 242202 G3: ground-instruction lines are categorically 'ground' from
345	    // structured context (this is the ground-instruction line builder) — not
346	    // inferred from the description string.
347	    category: 'ground',
348	    rateSource,
349	    unresolvedReason: getUnresolvedRateReason(input.resolution),
350	  };
351	}
