353	export function getZeroAmountReason(input: {
354	  isUnbillable?: boolean;
355	  invoiceTotal: number;
356	  groundResolution?: RateResolution;
357	  lineItems?: Array<{ qty?: number; quantity?: number; rate?: number }>;
358	  hasInstructor?: boolean;
359	}): RateResolutionReason | undefined {
360	  if (input.isUnbillable || input.invoiceTotal !== 0) return undefined;
361	  if (input.groundResolution && input.groundResolution.ok === false) {
362	    return input.groundResolution.reason;
363	  }
364	  if (input.hasInstructor === false) return 'no_instructor';
365	
366	  const hasBillableQuantity = (input.lineItems ?? []).some((line) => {
367	    const qty = parseFiniteNumber(line.qty ?? line.quantity) ?? 0;
368	    return qty > 0;
369	  });
370	  if (!hasBillableQuantity) return 'no_billable_duration';
371	
372	  const hasInvalidRate = (input.lineItems ?? []).some((line) => {
373	    const qty = parseFiniteNumber(line.qty ?? line.quantity) ?? 0;
374	    const rate = parseFiniteNumber(line.rate) ?? 0;
375	    return qty > 0 && rate <= 0;
376	  });
377	  if (hasInvalidRate) return 'missing_instructor_billing_rate';
378	
379	  return 'invalid_rate_configuration';
380	}
