123	function asRecord(value: unknown): Record<string, unknown> {
124	  return value && typeof value === 'object' && !Array.isArray(value)
125	    ? (value as Record<string, unknown>)
126	    : {};
127	}
128	
129	function normalizeText(value: unknown) {
130	  return typeof value === 'string' ? value.trim().toLowerCase() : '';
131	}
132	
133	function parseNonNegativeRate(value: unknown): number | null {
134	  if (value === null || value === undefined || value === '') return null;
135	  const rate = Number(value);
136	  return Number.isFinite(rate) && rate >= 0 ? rate : null;
137	}
138	
139	function roundCurrency(value: number) {
140	  return Math.round(value * 100) / 100;
141	}
142	
143	function allocateCurrencyShare(value: number, divisor = 1, shareIndex = 0) {
144	  const normalizedDivisor = Math.max(1, Math.trunc(divisor));
145	  const normalizedShareIndex = Math.min(
146	    normalizedDivisor - 1,
147	    Math.max(0, Math.trunc(shareIndex)),
148	  );
149	  const cents = Math.round(value * 100);
150	  const sign = cents < 0 ? -1 : 1;
151	  const absoluteCents = Math.abs(cents);
152	  const baseCents = Math.floor(absoluteCents / normalizedDivisor);
153	  const remainder = absoluteCents % normalizedDivisor;
154	  return (
155	    (sign * (baseCents + (normalizedShareIndex < remainder ? 1 : 0))) / 100
156	  );
157	}
