159	function isUsableContractBalance(balance: ProgramContractBalance) {
160	  const status = normalizeText(balance.status);
161	  const hasQuotedHourProduct =
162	    Array.isArray(balance.hourItems) &&
163	    balance.hourItems.some((item) => {
164	      const productId = item.productId?.trim() || item.lineItemTypeId?.trim();
165	      return Boolean(productId) && parseNonNegativeRate(item.rate) !== null;
166	    });
167	  const hasQuotedFeeProduct =
168	    Array.isArray(balance.feeItems) &&
169	    balance.feeItems.some((item) => {
170	      const productId = item.productId?.trim() || item.lineItemTypeId?.trim();
171	      return (
172	        Boolean(productId) &&
173	        (parseNonNegativeRate(item.rate) !== null ||
174	          parseNonNegativeRate(item.amount) !== null)
175	      );
176	    });
177	  return (
178	    Boolean(balance.id) &&
179	    status !== 'draft' &&
180	    status !== 'archived' &&
181	    status !== 'cancelled' &&
182	    (hasQuotedHourProduct || hasQuotedFeeProduct)
183	  );
184	}
