195	function getFallbackQuoteVersionId(balance: ProgramContractBalance) {
196	  const fundingDetails = asRecord(balance.fundingDetails);
197	  const explicitVersion =
198	    typeof fundingDetails.quoteVersionId === 'string'
199	      ? fundingDetails.quoteVersionId.trim()
200	      : '';
201	  if (explicitVersion) return explicitVersion;
202	
203	  const originalQuoteSnapshot = asRecord(fundingDetails.originalQuoteSnapshot);
204	  const capturedAt =
205	    typeof originalQuoteSnapshot.capturedAt === 'string'
206	      ? originalQuoteSnapshot.capturedAt.trim()
207	      : '';
208	  const versionMarker =
209	    capturedAt ||
210	    (balance.createdAt instanceof Date
211	      ? balance.createdAt.toISOString()
212	      : balance.createdAt?.trim()) ||
213	    (balance.updatedAt instanceof Date
214	      ? balance.updatedAt.toISOString()
215	      : balance.updatedAt?.trim()) ||
216	    'assigned';
217	  return `${balance.id}:${versionMarker}`;
218	}
