220	function normalizeIsoDate(value: unknown) {
221	  if (value instanceof Date) return value.toISOString().slice(0, 10);
222	  if (typeof value !== 'string') return '';
223	  const normalized = value.trim().slice(0, 10);
224	  return /^\d{4}-\d{2}-\d{2}$/.test(normalized) ? normalized : '';
225	}
