227	function getProgramContractQuoteVersions(
228	  balance: ProgramContractBalance,
229	): ProgramContractQuoteVersion[] {
230	  const fundingDetails = asRecord(balance.fundingDetails);
231	  const rawVersions = Array.isArray(fundingDetails.quoteVersions)
232	    ? fundingDetails.quoteVersions
233	    : [];
234	  return rawVersions
235	    .map((value) => {
236	      const record = asRecord(value);
237	      const id = typeof record.id === 'string' ? record.id.trim() : '';
238	      const effectiveFrom = normalizeIsoDate(record.effectiveFrom);
239	      if (!id || !effectiveFrom) return null;
240	      return {
241	        id,
242	        effectiveFrom,
243	        hourItems: Array.isArray(record.hourItems)
244	          ? (record.hourItems as ProgramContractHourItem[])
245	          : [],
246	        feeItems: Array.isArray(record.feeItems)
247	          ? (record.feeItems as ProgramContractFeeItem[])
248	          : [],
249	      };
250	    })
251	    .filter(
252	      (version): version is ProgramContractQuoteVersion => version !== null,
253	    )
254	    .sort((a, b) => a.effectiveFrom.localeCompare(b.effectiveFrom));
