257	function getApplicableProgramContractQuote(
258	  balance: ProgramContractBalance,
259	  eventDate?: string | null,
260	): ProgramContractQuoteVersion {
261	  const versions = getProgramContractQuoteVersions(balance);
262	  const normalizedEventDate = normalizeIsoDate(eventDate);
263	  const selectedVersion =
264	    versions.length === 0
265	      ? null
266	      : normalizedEventDate
267	        ? (versions
268	            .filter((version) => version.effectiveFrom <= normalizedEventDate)
269	            .at(-1) ?? versions[0])
270	        : versions.at(-1);
271	  if (selectedVersion) return selectedVersion;
272	  return {
273	    id: getFallbackQuoteVersionId(balance),
274	    effectiveFrom:
275	      normalizeIsoDate(balance.createdAt) ||
276	      normalizeIsoDate(balance.startDate) ||
277	      '1970-01-01',
278	    hourItems: balance.hourItems ?? [],
279	    feeItems: balance.feeItems ?? [],
280	  };
281	}
