283	/**
284	 * Select the program contract for an event without guessing across multiple
285	 * active programs. An explicit balance link always wins. Otherwise the
286	 * selector requires one unambiguous course/program match, or one usable plan.
287	 */
288	export function selectProgramContractBalance(
289	  balances: ProgramContractBalance[],
290	  context: ProgramContractSelectionContext = {},
291	): ProgramContractBalance | null {
292	  const usable = balances.filter(isUsableContractBalance);
293	  if (usable.length === 0) return null;
294	
295	  const requestedBalanceId = context.requestedBalanceId?.trim();
296	  if (requestedBalanceId) {
297	    return usable.find((balance) => balance.id === requestedBalanceId) ?? null;
298	  }
299	
300	  const courseId = context.courseId?.trim();
301	  if (courseId) {
302	    const courseMatches = usable.filter(
303	      (balance) => balance.courseId === courseId,
304	    );
305	    if (courseMatches.length === 1) return courseMatches[0];
306	    if (courseMatches.length > 1) return null;
307	  }
308	
309	  const programName = normalizeText(context.programName);
310	  if (programName) {
311	    const programMatches = usable.filter(
312	      (balance) => normalizeText(balance.programName) === programName,
313	    );
314	    if (programMatches.length === 1) return programMatches[0];
315	    if (programMatches.length > 1) return null;
316	  }
317	
318	  const courseName = normalizeText(context.courseName);
319	  if (courseName) {
320	    const courseMatches = usable.filter(
321	      (balance) => normalizeText(balance.courseName) === courseName,
322	    );
323	    if (courseMatches.length === 1) return courseMatches[0];
324	    if (courseMatches.length > 1) return null;
325	  }
326	
327	  return usable.length === 1 ? usable[0] : null;
328	}
