330	/**
331	 * Resolve one exact Billing Product against an assigned program quote.
332	 * Duplicate quote lines are safe when they all carry the same price. If the
333	 * same product has different prices inside the program, billing must retain
334	 * the legacy rate until the event has more specific course/quote-line context.
335	 */
336	export function resolveProgramContractRate(
337	  balance: ProgramContractBalance,
338	  productId: string,
339	  eventDate?: string | null,
340	): ProgramContractRateResolution {
341	  const normalizedProductId = productId.trim();
342	  const quote = getApplicableProgramContractQuote(balance, eventDate);
343	  const matchingHourLines = quote.hourItems
344	    .map((line, index) => ({
345	      line,
346	      index,
347	      linkedProductIds: [
348	        line.productId?.trim(),
349	        line.lineItemTypeId?.trim(),
350	      ].filter((value): value is string => Boolean(value)),
351	      rate: parseNonNegativeRate(line.rate),
352	      quoteLineId:
353	        line.id?.trim() || `${normalizedProductId}:hour:${index + 1}`,
354	    }))
355	    .filter(
356	      (candidate) =>
357	        candidate.linkedProductIds.includes(normalizedProductId) &&
358	        candidate.rate !== null,
359	    );
360	  const matchingFeeLines = quote.feeItems
361	    .map((line, index) => {
362	      const quantity = Math.max(1, Number(line.quantity) || 1);
363	      return {
364	        line,
365	        index,
366	        linkedProductIds: [
367	          line.productId?.trim(),
368	          line.lineItemTypeId?.trim(),
369	        ].filter((value): value is string => Boolean(value)),
370	        rate:
371	          parseNonNegativeRate(line.rate) ??
372	          (parseNonNegativeRate(line.amount) !== null
373	            ? (parseNonNegativeRate(line.amount) as number) / quantity
374	            : null),
375	        quoteLineId:
376	          line.id?.trim() || `${normalizedProductId}:fee:${index + 1}`,
377	      };
378	    })
379	    .filter(
380	      (candidate) =>
381	        candidate.linkedProductIds.includes(normalizedProductId) &&
382	        candidate.rate !== null,
383	    );
384	  const matchingLines = [...matchingHourLines, ...matchingFeeLines];
385	  const base = {
386	    productId: normalizedProductId,
387	    studentProgramBalanceId: balance.id,
388	    programName: getProgramContractName(balance),
389	    quoteVersionId: quote.id,
390	    matchingLineCount: matchingLines.length,
391	  };
392	  if (matchingLines.length === 0) {
393	    return { ...base, status: 'not_quoted' };
394	  }
395	
396	  const distinctRates = new Set(
397	    matchingLines.map((candidate) => candidate.rate as number),
398	  );
399	  if (distinctRates.size !== 1) {
400	    return { ...base, status: 'ambiguous' };
401	  }
402	
403	  const match = matchingLines[0];
404	  return {
405	    ...base,
406	    status: 'matched',
407	    rate: match.rate as number,
408	    quoteLineId: match.quoteLineId,
409	  };
410	}
