433	export function getProgramContractRateCards(
434	  balances: ProgramContractBalance[],
435	  currentProducts: Array<{ id: string; name: string }> = [],
436	): ProgramContractRateCard[] {
437	  const currentProductNames = new Map(
438	    currentProducts.map((product) => [product.id, product.name]),
439	  );
440	  return balances
441	    .filter((balance) => {
442	      const status = normalizeText(balance.status);
443	      return (
444	        isUsableContractBalance(balance) &&
445	        status !== 'completed' &&
446	        status !== 'inactive'
447	      );
448	    })
449	    .map((balance) => {
450	      const hourlyRates = (balance.hourItems ?? [])
451	        .map((line, index) => {
452	          const productId =
453	            line.productId?.trim() || line.lineItemTypeId?.trim() || '';
454	          const rate = parseNonNegativeRate(line.rate);
455	          if (!productId || rate === null) return null;
456	          const quoteLineId = line.id?.trim() || `${productId}:${index + 1}`;
457	          return {
458	            key: `${productId}:${rate}:${quoteLineId}`,
459	            quoteLineId,
460	            productId,
461	            productName:
462	              line.productName?.trim() || line.label?.trim() || productId,
463	            currentProductName: currentProductNames.get(productId),
464	            rate,
465	            rateUnit: 'hour' as const,
466	            hours: Math.max(0, Number(line.hours) || 0),
467	            quantity: 0,
468	          };
469	        })
470	        .filter((line): line is NonNullable<typeof line> => line !== null);
471	      const feeRates = (balance.feeItems ?? [])
472	        .map((line, index) => {
473	          const productId =
474	            line.productId?.trim() || line.lineItemTypeId?.trim() || '';
475	          const quantity = Math.max(1, Number(line.quantity) || 1);
476	          const amount = parseNonNegativeRate(line.amount);
477	          const rate =
478	            parseNonNegativeRate(line.rate) ??
479	            (amount === null ? null : amount / quantity);
480	          if (!productId || rate === null) return null;
481	          const quoteLineId =
482	            line.id?.trim() || `${productId}:fee:${index + 1}`;
483	          return {
484	            key: `${productId}:${rate}:${quoteLineId}`,
485	            quoteLineId,
486	            productId,
487	            productName:
488	              line.productName?.trim() || line.label?.trim() || productId,
489	            currentProductName: currentProductNames.get(productId),
490	            rate,
491	            rateUnit: 'item' as const,
492	            hours: 0,
493	            quantity,
494	            timing: line.timing?.trim() || undefined,
495	          };
496	        })
497	        .filter((line): line is NonNullable<typeof line> => line !== null);
498	      const rates = [...hourlyRates, ...feeRates];
499	      return {
500	        studentProgramBalanceId: balance.id,
501	        programName: getProgramContractName(balance),
502	        status: balance.status?.trim() || 'Active',
503	        rates,
504	      };
505	    })
506	    .filter((card) => card.rates.length > 0);
507	}
