523	export function applyProgramContractRatesToStoredInvoiceLines(
524	  lines: ProgramContractStoredInvoiceLine[],
525	  balance: ProgramContractBalance,
526	  options: { eventDate?: string | null } = {},
527	): {
528	  lines: ProgramContractStoredInvoiceLine[];
529	  appliedCount: number;
530	  total: number;
531	} {
532	  let appliedCount = 0;
533	  const resolvedLines = lines.map((line) => {
534	    if (line.isAuto !== true || hasManualStoredRateAdjustment(line)) {
535	      return line;
536	    }
537	    const productId =
538	      line.productId?.trim() || line.lineItemTypeId?.trim() || '';
539	    if (!productId) return line;
540	
541	    const resolution = resolveProgramContractRate(
542	      balance,
543	      productId,
544	      options.eventDate,
545	    );
546	    if (resolution.status !== 'matched' || resolution.rate === undefined) {
547	      return {
548	        ...line,
549	        productId,
550	        studentProgramBalanceId: balance.id,
551	        quoteVersionId: resolution.quoteVersionId,
552	        programName: resolution.programName,
553	        programRateResolution: resolution.status,
554	      };
555	    }
556	
557	    const quantity = Math.max(0, Number(line.quantity ?? line.qty) || 0);
558	    const divisor = Math.max(
559	      1,
560	      Math.trunc(Number(line.groupShareDivisor) || 1),
561	    );
562	    const shareIndex = Math.max(
563	      0,
564	      Math.trunc(Number(line.groupShareIndex) || 0),
565	    );
566	    const fullSubtotal = roundCurrency(quantity * resolution.rate);
567	    const taxRate = Math.max(0, Number(line.taxRate) || 0);
568	    const taxable =
569	      Boolean(line.taxCategoryId) &&
570	      line.taxCategoryId !== 'non_taxable' &&
571	      taxRate > 0 &&
572	      fullSubtotal > 0;
573	    const fullTaxAmount = taxable
574	      ? line.taxInclusive
575	        ? roundCurrency(fullSubtotal - fullSubtotal / (1 + taxRate / 100))
576	        : roundCurrency(fullSubtotal * (taxRate / 100))
577	      : 0;
578	    const subtotal = allocateCurrencyShare(fullSubtotal, divisor, shareIndex);
579	    const taxAmount = allocateCurrencyShare(fullTaxAmount, divisor, shareIndex);
580	    const amount =
581	      line.taxInclusive === true
582	        ? subtotal
583	        : roundCurrency(subtotal + taxAmount);
584	    const appliedRate = allocateCurrencyShare(
585	      resolution.rate,
586	      divisor,
587	      shareIndex,
588	    );
589	    appliedCount += 1;
590	    return {
591	      ...line,
592	      productId,
593	      rate: appliedRate,
594	      subtotal,
595	      taxAmount,
596	      amount,
597	      total: amount,
598	      studentProgramBalanceId: resolution.studentProgramBalanceId,
599	      quoteVersionId: resolution.quoteVersionId,
600	      quoteLineId: resolution.quoteLineId,
601	      quotedRate: resolution.rate,
602	      appliedRate,
603	      rateSource: ASSIGNED_PROGRAM_QUOTE_RATE_SOURCE,
604	      programName: resolution.programName,
605	      programRateResolution: 'matched' as const,
606	      seedRate: appliedRate,
607	      manualRateOverride: false,
608	      studentProductRateExceptionId: undefined,
609	      studentProductRateEffectiveFrom: undefined,
610	      studentProductRateEffectiveTo: undefined,
611	      productNameSnapshot: undefined,
612	    };
613	  });
614	
615	  return {
616	    lines: resolvedLines,
617	    appliedCount,
618	    total: roundCurrency(
619	      resolvedLines.reduce(
620	        (sum, line) => sum + (Number(line.amount ?? line.total) || 0),
621	        0,
622	      ),
623	    ),
624	  };
625	}
