349	function getOperationalRateMatchSource(
350	  product: TrainingPlanRateResolvableProduct,
351	): TrainingPlanHourBillingProduct['metadata']['operationalSource'] | null {
352	  if (
353	    product.attribution === 'instructor' ||
354	    product.attribution === 'simulator_instructor'
355	  ) {
356	    return 'instructor';
357	  }
358	  if (product.attribution === 'simulator') return 'simulator';
359	  if (product.attribution === 'aircraft') return 'aircraft';
360	  return null;
361	}
362	
363	function getOperationalSource(
364	  product: TrainingPlanRateResolvableProduct,
365	): TrainingPlanHourBillingProduct['metadata']['operationalSource'] | null {
366	  if (
367	    !product.metadata ||
368	    typeof product.metadata !== 'object' ||
369	    Array.isArray(product.metadata)
370	  ) {
371	    return null;
372	  }
373	  const source = (product.metadata as Record<string, unknown>)
374	    .operationalSource;
375	  return source === 'aircraft' ||
376	    source === 'simulator' ||
377	    source === 'instructor'
378	    ? source
379	    : null;
380	}
