382	/**
383	 * Resolves an unpriced catalog definition from the operational products shown
384	 * in Location Settings when every matching profile has the same current rate.
385	 *
386	 * If profile rates differ, the generic definition remains unpriced and the
387	 * administrator must select a specific aircraft, simulator, or instructor.
388	 */
389	export function resolveTrainingPlanHourBillingProductRates<
390	  T extends TrainingPlanRateResolvableProduct,
391	>(configuredProducts: T[], operationalProducts: T[]): T[] {
392	  return configuredProducts.map((product) => {
393	    if ((getOperationalProductRate(product.defaultRate) ?? 0) > 0) {
394	      return product;
395	    }
396	    const operationalSource = getOperationalRateMatchSource(product);
397	    if (!operationalSource) return product;
398	
399	    const matchingRates = operationalProducts
400	      .filter(
401	        (candidate) =>
402	          getOperationalSource(candidate) === operationalSource &&
403	          (operationalSource !== 'aircraft' ||
404	            !product.aircraftEngineType ||
405	            candidate.aircraftEngineType === product.aircraftEngineType),
406	      )
407	      .map((candidate) => getOperationalProductRate(candidate.defaultRate))
408	      .filter((rate): rate is number => Boolean(rate && rate > 0));
409	    const uniqueRates = [
410	      ...new Set(matchingRates.map((rate) => Math.round(rate * 100))),
411	    ];
412	    const [uniqueRate] = uniqueRates;
413	    if (uniqueRates.length !== 1 || uniqueRate === undefined) return product;
414	    return {
415	      ...product,
416	      defaultRate: uniqueRate / 100,
417	    } as T;
418	  });
419	}
