421	/**
422	 * Chooses the products already linked to a certificate as purchase defaults.
423	 * A dedicated Solo product is not selected when the certificate also has a
424	 * normal aircraft rental product because those are separate flight-hour uses.
425	 */
426	export function getDefaultTrainingPlanAdditionalHourProductIds({
427	  products,
428	  hourItems,
429	  allocationId,
430	  hourType,
431	}: {
432	  products: TrainingPlanRateResolvableProduct[];
433	  hourItems: TrainingPlanLinkedHourProductSource[];
434	  allocationId: string;
435	  hourType: TrainingPlanHourProductBucket;
436	}): string[] {
437	  const eligibleProducts = products.filter(
438	    (product) =>
439	      getTrainingPlanHourProductBucket(product) === hourType &&
440	      (getOperationalProductRate(product.defaultRate) ?? 0) > 0,
441	  );
442	  const eligibleProductsById = new Map(
443	    eligibleProducts.map((product) => [product.id, product]),
444	  );
445	  const linkedEntries = hourItems.flatMap((item) => {
446	    if (
447	      item.source === TRAINING_PLAN_ALLOCATION_PURCHASE_SOURCE ||
448	      item.groupSourceId !== allocationId ||
449	      item.bucket !== hourType ||
450	      typeof item.productId !== 'string'
451	    ) {
452	      return [];
453	    }
454	    const product = eligibleProductsById.get(item.productId);
455	    if (!product) return [];
456	    return [
457	      {
458	        product,
459	        descriptor: [
460	          item.label,
461	          item.productName,
462	          item.productHint,
463	          product.id,
464	          product.name,
465	        ]
466	          .filter(Boolean)
467	          .join(' ')
468	          .toLowerCase(),
469	      },
470	    ];
471	  });
472	  const hasStandardAircraftProduct = linkedEntries.some(
473	    ({ product, descriptor }) =>
474	      product.attribution === 'aircraft' && !descriptor.includes('solo'),
475	  );
476	  const linkedIds = [
477	    ...new Set(
478	      linkedEntries
479	        .filter(
480	          ({ product, descriptor }) =>
481	            !(
482	              hourType === 'flight' &&
483	              hasStandardAircraftProduct &&
484	              product.attribution === 'aircraft' &&
485	              descriptor.includes('solo')
486	            ),
487	        )
488	        .map(({ product }) => product.id),
489	    ),
490	  ];
491	  if (linkedIds.length > 0) return linkedIds;
492	  const [onlyEligibleProduct] = eligibleProducts;
493	  return eligibleProducts.length === 1 && onlyEligibleProduct
494	    ? [onlyEligibleProduct.id]
495	    : [];
496	}
