818	export function normalizeInvoiceRevenueBuckets(
819	  input: unknown,
820	): InvoiceRevenueBucket[] {
821	  if (!Array.isArray(input)) return DEFAULT_INVOICE_REVENUE_BUCKETS;
822	
823	  const seenIds = new Set<string>();
824	  const normalized = input
825	    .map((raw, index): InvoiceRevenueBucket | null => {
826	      if (!raw || typeof raw !== 'object') return null;
827	      const bucket = raw as Record<string, unknown>;
828	      const rawLabel =
829	        typeof bucket.label === 'string'
830	          ? bucket.label
831	          : typeof bucket.name === 'string'
832	            ? bucket.name
833	            : '';
834	      const label = rawLabel.trim();
835	      if (!label) return null;
836	
837	      const idCandidate =
838	        typeof bucket.id === 'string' && bucket.id.trim()
839	          ? slugifyInvoiceRevenueBucketId(bucket.id)
840	          : slugifyInvoiceRevenueBucketId(label);
841	      const id = idCandidate || `bucket-${index + 1}`;
842	      if (seenIds.has(id)) return null;
843	      seenIds.add(id);
844	
845	      const sortOrder =
846	        typeof bucket.sortOrder === 'number' &&
847	        Number.isFinite(bucket.sortOrder)
848	          ? bucket.sortOrder
849	          : index + 1;
850	
851	      return {
852	        id,
853	        label,
854	        sortOrder,
855	        quickBooksIncomeAccount: optionalTrimmedString(
856	          bucket.quickBooksIncomeAccount,
857	        ),
858	        quickBooksClass: optionalTrimmedString(bucket.quickBooksClass),
859	        quickBooksTaxCode: optionalTrimmedString(bucket.quickBooksTaxCode),
860	      };
861	    })
862	    .filter((bucket): bucket is InvoiceRevenueBucket => Boolean(bucket))
863	    .sort((a, b) => a.sortOrder - b.sortOrder);
864	
865	  if (normalized.length === 0) return DEFAULT_INVOICE_REVENUE_BUCKETS;
866	
867	  if (!seenIds.has('other')) {
868	    normalized.push({
869	      id: 'other',
870	      label: INVOICE_REVENUE_CATEGORY_LABELS.other,
871	      sortOrder: normalized.length + 1,
872	    });
873	  }
874	
875	  return normalized.map((bucket, index) => ({
876	    ...bucket,
877	    sortOrder: index + 1,
878	  }));
879	}
