919	function normalizeInvoiceRevenueCategory(
920	  value: unknown,
921	  name: string,
922	  attribution: InvoiceLineItemAttribution,
923	  validRevenueCategories: Set<string>,
924	): InvoiceRevenueCategory {
925	  const raw = typeof value === 'string' ? value.trim().toLowerCase() : '';
926	  if (validRevenueCategories.has(raw)) return raw;
927	
928	  const descriptor = name.trim().toLowerCase();
929	  const isInstruction =
930	    attribution === 'instructor' ||
931	    attribution === 'aircraft_instructor' ||
932	    attribution === 'simulator_instructor' ||
933	    textIncludesAny(descriptor, [
934	      'instruction',
935	      'instructor',
936	      'debrief',
937	      'ground school',
938	      'oral',
939	      'cfi',
940	    ]);
941	
942	  if (raw === 'ground') {
943	    return validOrFallbackRevenueBucketId(
944	      isInstruction ? 'instruction' : 'other',
945	      validRevenueCategories,
946	    );
947	  }
948	  if (raw === 'flight') {
949	    return validOrFallbackRevenueBucketId(
950	      isInstruction ? 'instruction' : 'airplane',
951	      validRevenueCategories,
952	    );
953	  }
954	  if (raw === 'fees') {
955	    if (textIncludesAny(descriptor, ['checkride', 'check ride', 'dpe'])) {
956	      return validOrFallbackRevenueBucketId(
957	        'checkride',
958	        validRevenueCategories,
959	      );
960	    }
961	    if (
962	      textIncludesAny(descriptor, [
963	        'knowledge test',
964	        'knowledge exam',
965	        'written test',
966	        'written exam',
967	      ])
968	    ) {
969	      return validOrFallbackRevenueBucketId(
970	        'knowledge',
971	        validRevenueCategories,
972	      );
973	    }
974	    return fallbackRevenueBucketId(validRevenueCategories);
975	  }
976	
977	  if (isInstruction)
978	    return validOrFallbackRevenueBucketId(
979	      'instruction',
980	      validRevenueCategories,
981	    );
982	  if (textIncludesAny(descriptor, ['simulator', 'sim '])) {
983	    return validOrFallbackRevenueBucketId('sim', validRevenueCategories);
984	  }
985	  if (textIncludesAny(descriptor, ['aircraft', 'airplane', 'flight time'])) {
986	    return validOrFallbackRevenueBucketId('airplane', validRevenueCategories);
987	  }
988	  if (textIncludesAny(descriptor, ['checkride', 'check ride', 'dpe'])) {
989	    return validOrFallbackRevenueBucketId('checkride', validRevenueCategories);
990	  }
991	  if (textIncludesAny(descriptor, ['knowledge exam', 'knowledge test'])) {
992	    return validOrFallbackRevenueBucketId('knowledge', validRevenueCategories);
993	  }
994	
995	  return fallbackRevenueBucketId(validRevenueCategories);
996	}
