1003	  if (!Array.isArray(input)) {
1004	    if (revenueBuckets === undefined) return DEFAULT_INVOICE_LINE_ITEM_TYPES;
1005	    return DEFAULT_INVOICE_LINE_ITEM_TYPES.map((item) => ({
1006	      ...item,
1007	      revenueCategory: validOrFallbackRevenueBucketId(
1008	        item.revenueCategory,
1009	        validRevenueCategories,
1010	      ),
1011	    }));
1012	  }
1013	
1014	  const normalized = input
1015	    .map((raw, index): InvoiceLineItemType | null => {
1016	      if (!raw || typeof raw !== 'object') return null;
1017	      const item = raw as Record<string, unknown>;
1018	      const id =
1019	        typeof item.id === 'string' && item.id.trim()
1020	          ? item.id.trim()
1021	          : `line-item-${index + 1}`;
1022	      const name =
1023	        typeof item.name === 'string' && item.name.trim()
1024	          ? item.name.trim()
1025	          : '';
1026	      if (!name) return null;
1027	
1028	      const parsedAttribution = validAttributions.has(
1029	        item.attribution as InvoiceLineItemAttribution,
1030	      )
1031	        ? (item.attribution as InvoiceLineItemAttribution)
1032	        : 'none';
1033	      const shouldRepairLegacySimulatorInstruction =
1034	        isCanonicalSimulatorInstructionProduct({ id }) &&
1035	        item.rateSource === undefined &&
1036	        parsedAttribution !== 'simulator_instructor';
1037	      const attribution = shouldRepairLegacySimulatorInstruction
1038	        ? 'simulator_instructor'
1039	        : parsedAttribution;
1040	      const rateSource =
1041	        item.rateSource === undefined &&
1042	        (id === 'fuel-surcharge' || id === 'landing-fees')
1043	          ? 'fixed'
1044	          : normalizeInvoiceLineItemRateSource(item.rateSource, attribution);
1045	      const aircraftEngineType = isAircraftLineItemAttribution(attribution)
1046	        ? (normalizeAircraftEngineType(item.aircraftEngineType) ??
1047	          inferAircraftEngineTypeFromProductName(name))
1048	        : undefined;
1049	      const revenueCategory = shouldRepairLegacySimulatorInstruction
1050	        ? validOrFallbackRevenueBucketId('instruction', validRevenueCategories)
1051	        : normalizeInvoiceRevenueCategory(
1052	            item.revenueCategory,
1053	            name,
1054	            attribution,
1055	            validRevenueCategories,
1056	          );
1057	      const defaultRate =
1058	        typeof item.defaultRate === 'number' &&
1059	        Number.isFinite(item.defaultRate) &&
1060	        item.defaultRate >= 0
1061	          ? item.defaultRate
1062	          : undefined;
1063	      const sortOrder =
1064	        typeof item.sortOrder === 'number' && Number.isFinite(item.sortOrder)
1065	          ? item.sortOrder
1066	          : index + 1;
1067	      const taxCategoryId = optionalTrimmedString(item.taxCategoryId);
1068	      const archivedAt = optionalTrimmedString(item.archivedAt);
1069	
1070	      return {
1071	        id,
1072	        name,
1073	        revenueCategory,
1074	        attribution,
1075	        rateSource,
1076	        aircraftEngineType,
1077	        defaultRate,
1078	        taxCategoryId:
1079	          taxCategoryId === 'aircraft_rental_tax' ? undefined : taxCategoryId,
1080	        quickBooksItemName: optionalTrimmedString(item.quickBooksItemName),
1081	        quickBooksItemId: optionalTrimmedString(item.quickBooksItemId),
1082	        active: archivedAt ? false : item.active !== false,
1083	        archivedAt,
1084	        archivedBy: optionalTrimmedString(item.archivedBy),
1085	        sortOrder,
1086	      };
1087	    })
1088	    .filter((item): item is InvoiceLineItemType => Boolean(item));
1089	
1090	  if (normalized.length === 0) return DEFAULT_INVOICE_LINE_ITEM_TYPES;
1091	
1092	  const normalizedIds = new Set(normalized.map((item) => item.id));
1093	  const hasCanonicalTrainingFeeCatalog = normalized.some((item) =>
1094	    ['checkride-fee', 'knowledge-exam-fee', 'books-materials'].includes(
1095	      item.id,
1096	    ),
1097	  );
1098	  const hasSimulatorInstructionProduct = normalized.some(
1099	    (item) => item.attribution === 'simulator_instructor',
1100	  );
1101	  const requiredDefaultIds = new Set([
1102	    'solo-flight',
1103	    ...(!hasSimulatorInstructionProduct ? ['simulator-instruction'] : []),
1104	    ...(hasCanonicalTrainingFeeCatalog
1105	      ? ['cfi-checkride-fee', 'admin-fee']
1106	      : []),
1107	  ]);
1108	  const missingRequiredDefaults = DEFAULT_INVOICE_LINE_ITEM_TYPES.filter(
