1110	  ).map((item) => ({
1111	    ...item,
1112	    revenueCategory: validOrFallbackRevenueBucketId(
1113	      item.revenueCategory,
1114	      validRevenueCategories,
1115	    ),
1116	  }));
1117	
1118	  return [...normalized, ...missingRequiredDefaults]
1119	    .sort((a, b) => a.sortOrder - b.sortOrder)
1120	    .map((item, index) => ({
1121	      ...item,
1122	      sortOrder: index + 1,
1123	    }));
1124	}
