1128	): InvoiceRevenueBucketCatalogValidationResult {
1129	  const normalized = normalizeInvoiceRevenueBuckets(input);
1130	  if (!Array.isArray(input)) {
1131	    return { valid: true, errors: [], normalized };
1132	  }
1133	
1134	  const errors: string[] = [];
1135	  const seenLabels = new Map<string, string>();
1136	
1137	  input.forEach((raw, index) => {
1138	    if (!raw || typeof raw !== 'object') {
1139	      errors.push(`Revenue bucket ${index + 1} is invalid`);
1140	      return;
1141	    }
1142	
1143	    const bucket = raw as Record<string, unknown>;
1144	    const label =
1145	      typeof bucket.label === 'string'
1146	        ? bucket.label.trim()
1147	        : typeof bucket.name === 'string'
1148	          ? bucket.name.trim()
1149	          : '';
1150	    if (!label) {
1151	      errors.push(`Revenue bucket ${index + 1} needs a name`);
1152	      return;
1153	    }
1154	
1155	    const normalizedLabel = label.toLowerCase();
1156	    const previousLabel = seenLabels.get(normalizedLabel);
