1275	 * use this same catalog instead of relying only on the separate Products table.
1276	 */
1277	export function getTrainingPlanHourBillingProducts(
1278	  input: unknown,
1279	  revenueBuckets?: unknown,
1280	): TrainingPlanHourBillingProduct[] {
1281	  return normalizeInvoiceLineItemTypes(input, revenueBuckets)
1282	    .filter((item) => item.active && item.attribution !== 'none')
1283	    .map((item) => {
1284	      const productType =
1285	        item.attribution === 'aircraft'
1286	          ? ('aircraft_rental' as const)
1287	          : item.attribution === 'simulator'
1288	            ? ('simulator' as const)
1289	            : ('service' as const);
1290	      return {
1291	        id: item.id,
1292	        name: item.name,
1293	        productType,
1294	        pricingModel: 'hourly' as const,
1295	        defaultRate: item.defaultRate,
1296	        unitLabel: 'hr' as const,
1297	        hoursUnit: 'hr' as const,
1298	        rateTypeTag: item.attribution,
1299	        status: 'active' as const,
1300	        taxCategory: item.taxCategoryId ?? null,
1301	        revenueCategory: item.revenueCategory,
1302	        attribution: item.attribution,
1303	        aircraftEngineType: item.aircraftEngineType,
1304	        metadata: {
1305	          lineItemTypeId: item.id,
1306	          revenueCategory: item.revenueCategory,
1307	          attribution: item.attribution,
1308	          taxCategoryId: item.taxCategoryId ?? null,
1309	        },
1310	      };
1311	    })
1312	    .sort((a, b) => a.name.localeCompare(b.name));
1313	}
1314	
1315	export function findInvoiceLineItemTypeByDescription(
1316	  lineItemTypes: InvoiceLineItemType[],
1317	  description: string,
1318	): InvoiceLineItemType | undefined {
1319	  const normalizedDescription = description.trim().toLowerCase();
1320	  if (!normalizedDescription) return undefined;
1321	
1322	  return lineItemTypes.find((item) => {
1323	    const name = item.name.trim().toLowerCase();
1324	    return (
1325	      normalizedDescription === name ||
1326	      normalizedDescription.startsWith(`${name}:`)
1327	    );
1328	  });
1329	}
