1	import { isPrepaidTrainingPurchaseMetadata } from '@/lib/billing/prepaid-training-purchase';
2	import { withTransaction } from '@/lib/db';
3	import * as schema from '@/lib/schema';
4	import { and, eq } from 'drizzle-orm';
5	
6	type FinalizePrepaidHourAllocationInput = {
7	  orgId: string;
8	  locationId: string;
9	  studentId: string;
10	  invoiceId: string;
11	  settledAt?: Date;
12	};
13	
14	function recordValue(value: unknown): Record<string, unknown> {
15	  return value && typeof value === 'object' && !Array.isArray(value)
16	    ? (value as Record<string, unknown>)
17	    : {};
18	}
19	
20	function recordArray(value: unknown): Record<string, unknown>[] {
21	  return Array.isArray(value)
22	    ? value.filter(
23	        (entry): entry is Record<string, unknown> =>
24	          !!entry && typeof entry === 'object' && !Array.isArray(entry),
25	      )
26	    : [];
27	}
28	
29	function finiteNonNegative(value: unknown): number | null {
30	  const number = Number(value);
31	  return Number.isFinite(number) && number >= 0 ? number : null;
32	}
33	
34	/**
35	 * Makes a purchased hour allocation usable only after its combined payment
36	 * settles. The invoice metadata contains the server-calculated allocation
37	 * snapshot, so retries and ACH webhook completion are idempotent.
38	 */
39	export async function finalizePrepaidHourAllocation(
40	  input: FinalizePrepaidHourAllocationInput,
41	) {
42	  const settledAt = input.settledAt ?? new Date();
43	  return withTransaction(async (tx) => {
44	    const [invoice] = await tx
45	      .select({
46	        id: schema.studentInvoices.id,
47	        metadata: schema.studentInvoices.metadata,
48	      })
49	      .from(schema.studentInvoices)
50	      .where(
51	        and(
52	          eq(schema.studentInvoices.id, input.invoiceId),
53	          eq(schema.studentInvoices.flightSchoolId, input.orgId),
54	          eq(schema.studentInvoices.locationId, input.locationId),
55	          eq(schema.studentInvoices.studentId, input.studentId),
56	        ),
57	      )
58	      .for('update')
59	      .limit(1);
60	    if (!invoice) return null;
61	
62	    const metadata = recordValue(invoice.metadata);
63	    if (
64	      !isPrepaidTrainingPurchaseMetadata(metadata) ||
65	      metadata.deferHourAllocationUntilPayment !== true
66	    ) {
67	      return null;
68	    }
69	    const trainingPlanBalanceId =
70	      typeof metadata.trainingPlanBalanceId === 'string'
71	        ? metadata.trainingPlanBalanceId
72	        : '';
73	    if (!trainingPlanBalanceId) {
74	      throw new Error(
75	        'Prepaid hour purchase is missing its training plan reference',
76	      );
77	    }
78	
79	    const [trainingPlan] = await tx
80	      .select()
81	      .from(schema.studentCourseBalances)
82	      .where(
83	        and(
84	          eq(schema.studentCourseBalances.id, trainingPlanBalanceId),
85	          eq(schema.studentCourseBalances.flightSchoolId, input.orgId),
86	          eq(schema.studentCourseBalances.locationId, input.locationId),
87	          eq(schema.studentCourseBalances.studentId, input.studentId),
88	        ),
89	      )
90	      .for('update')
91	      .limit(1);
92	    if (!trainingPlan) {
93	      throw new Error('Training plan is no longer available');
94	    }
95	
96	    if (typeof metadata.hourAllocationAppliedAt === 'string') {
97	      return trainingPlan;
98	    }
99	
100	    const pendingCourseAllocations = recordArray(
101	      metadata.pendingCourseAllocations,
102	    );
103	    const pendingHourItems = recordArray(
104	      metadata.pendingHourItems,
105	    ) as NonNullable<
106	      (typeof schema.studentCourseBalances.$inferInsert)['hourItems']
107	    >;
108	    const flightHoursTotal = finiteNonNegative(
109	      metadata.pendingFlightHoursTotal,
110	    );
111	    const groundHoursTotal = finiteNonNegative(
112	      metadata.pendingGroundHoursTotal,
113	    );
114	    const simulatorHoursTotal = finiteNonNegative(
115	      metadata.pendingSimulatorHoursTotal,
116	    );
117	    if (
118	      pendingCourseAllocations.length === 0 ||
119	      pendingHourItems.length === 0 ||
120	      flightHoursTotal === null ||
121	      groundHoursTotal === null ||
122	      simulatorHoursTotal === null
123	    ) {
124	      throw new Error(
125	        'Prepaid hour purchase allocation snapshot is incomplete',
126	      );
127	    }
128	
129	    const adjustmentId =
130	      typeof metadata.allocationAdjustmentId === 'string'
131	        ? metadata.allocationAdjustmentId
132	        : '';
133	    const appliedAt = settledAt.toISOString();
134	    const fundingDetails = recordValue(trainingPlan.fundingDetails);
135	    fundingDetails.courseAllocations = pendingCourseAllocations;
136	    fundingDetails.allocationAdjustmentHistory = recordArray(
137	      fundingDetails.allocationAdjustmentHistory,
138	    ).map((entry) =>
139	      entry.id === adjustmentId || entry.invoiceId === input.invoiceId
140	        ? {
141	            ...entry,
142	            collectionStatus: 'paid',
143	            allocationAppliedAt: appliedAt,
144	          }
145	        : entry,
146	    );
147	    fundingDetails.allocationAdjustmentCharges = recordArray(
148	      fundingDetails.allocationAdjustmentCharges,
149	    ).map((entry) =>
150	      entry.adjustmentId === adjustmentId || entry.invoiceId === input.invoiceId
151	        ? {
152	            ...entry,
153	            status: 'paid',
154	            allocationAppliedAt: appliedAt,
155	          }
156	        : entry,
157	    );
158	
159	    const [updatedTrainingPlan] = await tx
160	      .update(schema.studentCourseBalances)
161	      .set({
162	        fundingDetails,
163	        hourItems: pendingHourItems,
164	        flightHoursTotal,
165	        groundHoursTotal,
166	        simulatorHoursTotal,
167	        lastUpdated: settledAt,
168	        updatedAt: settledAt,
169	      })
170	      .where(
171	        and(
172	          eq(schema.studentCourseBalances.id, trainingPlanBalanceId),
173	          eq(schema.studentCourseBalances.flightSchoolId, input.orgId),
174	          eq(schema.studentCourseBalances.locationId, input.locationId),
175	          eq(schema.studentCourseBalances.studentId, input.studentId),
176	        ),
177	      )
178	      .returning();
179	    if (!updatedTrainingPlan) {
180	      throw new Error('Prepaid hour allocation update returned no row');
181	    }
182	
183	    await tx
184	      .update(schema.studentInvoices)
185	      .set({
186	        metadata: {
187	          ...metadata,
188	          hourAllocationAppliedAt: appliedAt,
189	        },
190	        updatedAt: settledAt,
191	      })
192	      .where(eq(schema.studentInvoices.id, input.invoiceId));
193	
194	    return updatedTrainingPlan;
195	  });
196	}
