72	function lineItemAmountCents(item: InvoiceProcessingFeeLineItem) {
73	  if (typeof item.amount === 'number' && Number.isFinite(item.amount)) {
74	    return Math.round(item.amount * 100);
75	  }
76	  const quantity =
77	    typeof item.quantity === 'number' && Number.isFinite(item.quantity)
78	      ? item.quantity
79	      : 1;
80	  const rate =
81	    typeof item.rate === 'number' && Number.isFinite(item.rate) ? item.rate : 0;
82	  return Math.round(quantity * rate * 100);
83	}
