85	function invoiceSubtotalCents(invoice: SettlementInvoice) {
86	  const lineItems = Array.isArray(invoice.lineItems)
87	    ? (invoice.lineItems as InvoiceProcessingFeeLineItem[])
88	    : [];
89	  const processingFeeCents = lineItems
90	    .filter(isProcessingFeeLineItem)
91	    .reduce((sum, item) => sum + lineItemAmountCents(item), 0);
