244	async function resolvePaymentMethod(args: {
245	  orgId: string;
246	  locationId: string;
247	  studentId: string;
248	  defaultCardId: string | null;
249	  customerId: string;
250	  customerStripeAccountId: string | null;
251	}) {
252	  const methods = await mvpRepository.studentPaymentCards.findByStudent(
253	    args.orgId,
254	    args.locationId,
255	    args.studentId,
256	  );
257	  const selected =
258	    (args.defaultCardId
259	      ? methods.find((method) => method.id === args.defaultCardId)
260	      : null) ??
261	    methods.find((method) => method.isDefault) ??
262	    methods[0] ??
263	    null;
264	
265	  if (!selected) {
266	    throw new PaymentPreferenceSettlementError(
267	      'PAYMENT_METHOD_REQUIRED',
268	      'No saved payment method is available for automatic billing.',
269	    );
270	  }
271	  if (!selected.stripePaymentMethodId) {
272	    throw new PaymentPreferenceSettlementError(
273	      'STRIPE_PAYMENT_METHOD_REQUIRED',
274	      'The saved payment method is not backed by Stripe.',
275	    );
276	  }
277	  if (selected.isBlocked) {
278	    throw new PaymentPreferenceSettlementError(
279	      'STRIPE_PAYMENT_METHOD_BLOCKED',
280	      'The saved payment method is blocked.',
281	    );
282	  }
283	  if (selected.isVerified === false) {
284	    throw new PaymentPreferenceSettlementError(
285	      'STRIPE_PAYMENT_METHOD_UNVERIFIED',
286	      'The saved payment method has not been verified yet.',
287	    );
288	  }
289	
290	  const localType = selected.type ?? 'card';
291	  if (localType !== 'card' && localType !== 'us_bank_account') {
292	    throw new PaymentPreferenceSettlementError(
293	      'STRIPE_PAYMENT_METHOD_UNSUPPORTED',
294	      'The saved payment method type is not supported for automatic billing.',
295	    );
296	  }
297	
298	  const schoolStripe = await getSchoolStripeService(args.orgId);
299	  schoolStripe.assertCustomerBoundary(args.customerStripeAccountId);
300	  const pm = await schoolStripe.retrievePaymentMethod(
301	    selected.stripePaymentMethodId,
302	  );
303	  const pmCustomer = stripePaymentMethodCustomerId(pm);
304	  if (pmCustomer && pmCustomer !== args.customerId) {
305	    throw new PaymentPreferenceSettlementError(
306	      'STRIPE_PAYMENT_METHOD_CUSTOMER_MISMATCH',
307	      "The saved payment method is not attached to this student's Stripe customer.",
308	    );
309	  }
310	  if (pm.type !== localType) {
311	    throw new PaymentPreferenceSettlementError(
312	      'STRIPE_PAYMENT_METHOD_TYPE_MISMATCH',
313	      'The saved payment method type does not match Stripe.',
314	    );
315	  }
316	  if (pm.type === 'us_bank_account') {
317	    const bankStatus = (pm.us_bank_account as { status?: string } | null)
318	      ?.status;
319	    if (bankStatus !== 'verified') {
320	      throw new PaymentPreferenceSettlementError(
321	        'STRIPE_PAYMENT_METHOD_UNVERIFIED',
322	        'The bank account is not verified and cannot be charged.',
323	      );
324	    }
325	  }
326	
327	  return {
328	    schoolStripe,
329	    selected,
330	    paymentMethodType: pm.type as 'card' | 'us_bank_account',
331	  };
332	}
