334	export async function settleInvoiceByPaymentPreference(args: {
335	  orgId: string;
336	  locationId: string;
337	  studentId: string;
338	  invoiceId: string;
339	  actor?: string | null;
340	  requestIp?: string | null;
341	  userAgent?: string | null;
342	  now?: Date;
343	}): Promise<PaymentPreferenceSettlementResult> {
344	  const now = args.now ?? new Date();
345	  let invoice = await mvpRepository.studentInvoices.findByIdForLocation(
346	    args.orgId,
347	    args.locationId,
348	    args.invoiceId,
349	  );
350	  if (!invoice) {
351	    throw new PaymentPreferenceSettlementError(
352	      'INVOICE_NOT_FOUND',
353	      'Invoice not found for automatic settlement.',
354	    );
355	  }
356	
357	  const preference =
358	    await mvpRepository.studentPaymentPreferences.findByStudent(
359	      args.orgId,
360	      args.locationId,
361	      args.studentId,
362	    );
363	  const source = normalizePreferenceSource({
364	    source: preference?.source,
365	    autopayEnabled: preference?.autopayEnabled,
366	  });
367	
368	  if (
369	    invoice.amount <= 0 ||
370	    !isBalanceImpactingSettlementStatus(invoice.status) ||
371	    !isDebitInvoiceForSettlement(invoice)
372	  ) {
373	    return {
374	      source,
375	      invoiceId: invoice.id,
376	      accountBalanceAppliedCents: 0,
377	      externalSubtotalCents: 0,
378	      processingFeeCents: 0,
379	      externalChargeCents: 0,
380	      status: 'skipped',
381	    };
382	  }
383	
384	  if (source === 'smart') {
385	    await autoApplyBalanceToInvoices(
386	      args.orgId,
387	      args.locationId,
388	      args.studentId,
389	    );
390	    invoice = await mvpRepository.studentInvoices.findByIdForLocation(
391	      args.orgId,
392	      args.locationId,
393	      args.invoiceId,
394	    );
395	    if (!invoice) {
396	      throw new PaymentPreferenceSettlementError(
397	        'INVOICE_NOT_FOUND',
398	        'Invoice disappeared during automatic settlement.',
399	      );
400	    }
401	  }
402	
403	  const payments = await findInvoicePayments({
404	    orgId: args.orgId,
405	    locationId: args.locationId,
406	    studentId: args.studentId,
407	    invoiceId: invoice.id,
408	  });
409	  const subtotalCents = invoiceSubtotalCents(invoice);
410	  const appliedBalanceCents = accountBalancePaidCents(payments);
411	  const existingExternalCents = externalSubmittedCents(payments);
412	
413	  if (existingExternalCents > 0) {
414	    return {
415	      source,
416	      invoiceId: invoice.id,
417	      accountBalanceAppliedCents: appliedBalanceCents,
418	      externalSubtotalCents: 0,
419	      processingFeeCents: 0,
420	      externalChargeCents: existingExternalCents,
421	      status: 'already_settled',
422	    };
423	  }
424	
425	  if (source === 'balance') {
426	    await autoApplyBalanceToInvoices(
427	      args.orgId,
428	      args.locationId,
429	      args.studentId,
430	    );
431	    invoice = await mvpRepository.studentInvoices.findByIdForLocation(
432	      args.orgId,
433	      args.locationId,
434	      args.invoiceId,
435	    );
436	    if (!invoice) {
437	      throw new PaymentPreferenceSettlementError(
438	        'INVOICE_NOT_FOUND',
439	        'Invoice disappeared during automatic settlement.',
440	      );
441	    }
442	    const refreshedPayments = await findInvoicePayments({
443	      orgId: args.orgId,
444	      locationId: args.locationId,
445	      studentId: args.studentId,
446	      invoiceId: invoice.id,
447	    });
448	    const refreshedAccountBalanceAppliedCents =
449	      accountBalancePaidCents(refreshedPayments);
450	    const remaining = Math.max(
451	      0,
452	      invoiceSubtotalCents(invoice) - refreshedAccountBalanceAppliedCents,
453	    );
454	    return {
455	      source,
456	      invoiceId: invoice.id,
457	      accountBalanceAppliedCents: refreshedAccountBalanceAppliedCents,
458	      externalSubtotalCents: 0,
459	      processingFeeCents: 0,
460	      externalChargeCents: 0,
461	      status: remaining <= 0 ? 'account_balance' : 'skipped',
462	    };
463	  }
464	
465	  const externalSubtotalCents = Math.max(
466	    0,
467	    subtotalCents - appliedBalanceCents,
468	  );
469	  if (externalSubtotalCents <= 0) {
470	    await markInvoicePaidByAccountBalance({
471	      orgId: args.orgId,
472	      locationId: args.locationId,
473	      studentId: args.studentId,
474	      invoice,
475	      amountCents: 0,
476	      now,
477	      source,
478	    });
479	    return {
480	      source,
481	      invoiceId: invoice.id,
482	      accountBalanceAppliedCents: appliedBalanceCents,
483	      externalSubtotalCents: 0,
484	      processingFeeCents: 0,
485	      externalChargeCents: 0,
486	      status: 'account_balance',
487	    };
488	  }
489	
490	  const [studentUser] = await db
491	    .select({
492	      stripeCustomerId: schema.users.stripeCustomerId,
493	      stripeAccountId: schema.users.stripeAccountId,
494	    })
495	    .from(schema.users)
496	    .where(eq(schema.users.id, args.studentId))
497	    .limit(1);
498	  if (!studentUser?.stripeCustomerId) {
499	    throw new PaymentPreferenceSettlementError(
500	      'STRIPE_CUSTOMER_REQUIRED',
501	      'A Stripe customer mapping is required before automatic billing.',
502	    );
503	  }
504	
505	  const { schoolStripe, selected, paymentMethodType } =
506	    await resolvePaymentMethod({
507	      orgId: args.orgId,
508	      locationId: args.locationId,
509	      studentId: args.studentId,
510	      defaultCardId: preference?.defaultCardId ?? null,
511	      customerId: studentUser.stripeCustomerId,
512	      customerStripeAccountId: studentUser.stripeAccountId,
513	    });
514	  const stripePaymentMethodId = selected.stripePaymentMethodId;
515	  if (!stripePaymentMethodId) {
516	    throw new PaymentPreferenceSettlementError(
517	      'STRIPE_PAYMENT_METHOD_REQUIRED',
518	      'The saved payment method is not backed by Stripe.',
519	    );
520	  }
521	
522	  const processingFeeSettings =
523	    await mvpRepository.locationConfig.findSettingsByLocation(args.locationId);
524	  const feeAdjustedInvoice = buildInvoiceLineItemsWithProcessingFee({
525	    lineItems: Array.isArray(invoice.lineItems)
526	      ? (invoice.lineItems as InvoiceProcessingFeeLineItem[])
527	      : [],
528	    invoiceAmountCents: invoice.amount,
529	    settings: processingFeeSettings as Record<string, unknown> | null,
530	    paymentMethodType,
531	    feeBaseCents: externalSubtotalCents,
532	  });
533	  const externalChargeCents =
534	    externalSubtotalCents + feeAdjustedInvoice.processingFeeCents;
535	  const idempotencyKey = createHash('sha256')
536	    .update(
537	      `${invoice.id}:${stripePaymentMethodId}:${externalChargeCents}:automatic`,
538	    )
539	    .digest('hex');
540	
541	  const [existingAttempt] = await db
542	    .select({
543	      id: schema.studentPaymentHistory.id,
544	      status: schema.studentPaymentHistory.status,
545	      stripePaymentIntentId: schema.studentPaymentHistory.stripePaymentIntentId,
546	    })
547	    .from(schema.studentPaymentHistory)
548	    .where(
549	      and(
550	        eq(schema.studentPaymentHistory.flightSchoolId, args.orgId),
551	        eq(schema.studentPaymentHistory.locationId, args.locationId),
552	        eq(schema.studentPaymentHistory.studentId, args.studentId),
553	        eq(schema.studentPaymentHistory.invoiceId, invoice.id),
554	        eq(schema.studentPaymentHistory.idempotencyKey, idempotencyKey),
555	        inArray(schema.studentPaymentHistory.status, [
556	          'completed',
557	          'processing',
558	        ]),
559	      ),
560	    )
561	    .limit(1);
562	  if (existingAttempt) {
563	    return {
564	      source,
565	      invoiceId: invoice.id,
566	      accountBalanceAppliedCents: appliedBalanceCents,
567	      externalSubtotalCents,
568	      processingFeeCents: feeAdjustedInvoice.processingFeeCents,
569	      externalChargeCents,
570	      status: 'already_settled',
571	    };
572	  }
573	
574	  const pmLabel = paymentMethodLabel({
575	    type: paymentMethodType,
576	    brand: selected.brand,
577	    last4: selected.last4,
578	  });
579	
580	  let paymentIntent: Stripe.PaymentIntent;
581	  try {
582	    const piParams: Stripe.PaymentIntentCreateParams = {
583	      amount: externalChargeCents,
584	      currency: 'usd',
585	      customer: studentUser.stripeCustomerId,
586	      payment_method: stripePaymentMethodId,
587	      confirm: true,
588	      off_session: true,
589	      description: `Invoice payment - ${invoice.description ?? invoice.id}`,
590	      metadata: {
591	        invoiceId: invoice.id,
592	        studentId: args.studentId,
593	        locationId: args.locationId,
594	        paymentPreferenceSource: source,
595	      },
596	    };
597	
598	    if (paymentMethodType === 'us_bank_account') {
599	      piParams.payment_method_options = {
600	        us_bank_account: {
601	          transaction_purpose: 'services',
602	        },
603	      };
604	      piParams.mandate_data = {
605	        customer_acceptance: {
606	          type: 'online',
607	          online: {
608	            ip_address: args.requestIp ?? '127.0.0.1',
609	            user_agent: args.userAgent ?? 'ATOS-System',
610	          },
611	          accepted_at: Math.floor(now.getTime() / 1000),
612	        },
613	      };
614	    }
615	
616	    paymentIntent = await schoolStripe.createPaymentIntent(piParams, {
617	      idempotencyKey,
618	    });
619	  } catch (err: unknown) {
620	    const stripeErr = err as {
621	      code?: string;
622	      decline_code?: string;
623	      payment_intent?: { id?: string };
624	    } | null;
625	    await mvpRepository.studentPayments
626	      .createWithBalanceUpdate(args.orgId, args.locationId, args.studentId, {
627	        amount: externalChargeCents,
628	        description:
629	          paymentMethodType === 'us_bank_account'
630	            ? 'ACH Charge (Failed)'
631	            : 'Card Charge (Failed)',
632	        status: 'failed',
633	        paymentMethod: pmLabel,
634	        invoiceId: invoice.id,
635	        balanceDeltaCents: 0,
636	        reference: stripeErr?.decline_code ?? stripeErr?.code ?? null,
637	        idempotencyKey,
638	        failureCode: stripeErr?.decline_code ?? stripeErr?.code ?? null,
639	        paymentMethodType,
640	        stripePaymentIntentId: stripeErr?.payment_intent?.id ?? null,
641	      })
642	      .catch(() => undefined);
643	    return {
644	      source,
645	      invoiceId: invoice.id,
646	      accountBalanceAppliedCents: appliedBalanceCents,
647	      externalSubtotalCents,
648	      processingFeeCents: feeAdjustedInvoice.processingFeeCents,
649	      externalChargeCents,
650	      status: 'failed',
651	      error:
652	        err instanceof SchoolStripeServiceError || err instanceof Error
653	          ? err.message
654	          : String(err),
655	    };
656	  }
657	
658	  const isProcessing = paymentIntent.status === 'processing';
659	  const isSucceeded = paymentIntent.status === 'succeeded';
660	  if (!isProcessing && !isSucceeded) {
661	    return {
662	      source,
663	      invoiceId: invoice.id,
664	      accountBalanceAppliedCents: appliedBalanceCents,
665	      externalSubtotalCents,
666	      processingFeeCents: feeAdjustedInvoice.processingFeeCents,
667	      externalChargeCents,
668	      status: 'failed',
669	      error: `Payment did not succeed (status: ${paymentIntent.status})`,
670	    };
671	  }
672	
673	  const latestCharge = paymentIntent.latest_charge;
674	  const stripeChargeId =
675	    typeof latestCharge === 'string'
676	      ? latestCharge
677	      : (latestCharge?.id ?? null);
678	
679	  try {
680	    await mvpRepository.studentPayments.createWithBalanceUpdate(
681	      args.orgId,
682	      args.locationId,
683	      args.studentId,
