690	        status: isProcessing ? 'processing' : 'completed',
691	        paymentMethod: pmLabel,
692	        invoiceId: invoice.id,
693	        balanceDeltaCents: isSucceeded ? externalChargeCents : 0,
694	        reference: paymentIntent.id,
695	        idempotencyKey,
696	        paymentMethodType,
697	        stripePaymentIntentId: paymentIntent.id,
698	        stripeAccountId: schoolStripe.accountId,
699	        stripeChargeId,
700	        paymentDate: now,
701	      },
702	    );
703	  } catch (err) {
704	    if (!isDuplicateSettlementError(err)) throw err;
705	    // A concurrent settlement already recorded this payment. The card was
706	    // charged only once (Stripe idempotency key), and the winner owns the
707	    // invoice update — so we stop here to avoid double-crediting and report
708	    // success rather than a scary failure.
709	    logger.info(
710	      '[payment-preference] settled concurrently; skipping duplicate insert',
711	      {
712	        invoiceId: invoice.id,
713	        orgId: args.orgId,
714	        locationId: args.locationId,
715	        stripePaymentIntentId: paymentIntent.id,
716	      },
717	    );
718	    return {
719	      source,
720	      invoiceId: invoice.id,
721	      accountBalanceAppliedCents: appliedBalanceCents,
722	      externalSubtotalCents,
723	      processingFeeCents: feeAdjustedInvoice.processingFeeCents,
724	      externalChargeCents,
725	      status: 'already_settled',
726	    };
727	  }
728	
729	  const metadata = (invoice.metadata ?? {}) as Record<string, unknown>;
730	  const balanceImpactSign = invoice.balanceImpactCents > 0 ? 1 : -1;
731	  await mvpRepository.studentInvoices.updateWithBalanceAdjust(
732	    args.orgId,
733	    invoice.id,
734	    args.studentId,
735	    {
736	      status: invoice.status,
737	      amount: invoice.amount,
738	      balanceImpactCents: invoice.balanceImpactCents,
739	    },
740	    {
741	      status: isProcessing ? 'pending_settlement' : 'Completed',
742	      paidAt: isSucceeded ? now : undefined,
743	      amount: feeAdjustedInvoice.totalCents,
744	      balanceImpact: (balanceImpactSign * feeAdjustedInvoice.totalCents) / 100,
745	      lineItems: feeAdjustedInvoice.lineItems,
746	      metadata: {
747	        ...metadata,
748	        autoBilled: true,
749	        paymentPreferenceSource: source,
750	        accountBalanceAppliedCents: appliedBalanceCents,
751	        externalSubtotalCents,
752	        processingFeeCents: feeAdjustedInvoice.processingFeeCents,
753	        externalChargeCents,
754	        chargedAt: now.toISOString(),
755	        chargedBy: args.actor ?? 'System',
756	        ...(isProcessing ? { achSettlementPending: true } : {}),
757	      },
758	    },
759	  );
760	
761	  return {
762	    source,
763	    invoiceId: invoice.id,
764	    accountBalanceAppliedCents: appliedBalanceCents,
765	    externalSubtotalCents,
766	    processingFeeCents: feeAdjustedInvoice.processingFeeCents,
767	    externalChargeCents,
768	    status: isProcessing ? 'processing' : 'charged',
769	  };
770	}
