360	function paymentContributionCents(
361	  payment: typeof schema.studentPaymentHistory.$inferSelect,
362	  options: { countAccountBalance?: boolean } = {},
363	) {
364	  const status = String(payment.status ?? '').toLowerCase();
365	  if (status !== 'completed') return 0;
366	  if (isRefundPaymentHistoryRow(payment)) return 0;
367	  if (
368	    options.countAccountBalance === false &&
369	    isAccountBalancePaymentHistoryRow(payment)
370	  ) {
371	    return 0;
372	  }
373	  const delta =
374	    typeof payment.balanceDelta === 'number'
375	      ? payment.balanceDelta
376	      : payment.balanceDelta == null
377	        ? null
378	        : Number(payment.balanceDelta);
379	  if (delta != null && Number.isFinite(delta) && delta !== 0) {
380	    return Math.max(0, Math.round(delta));
381	  }
382	  return Math.max(0, payment.amount);
383	}
