397	function hasLikelyUnfundedAccountBalanceSettlement(
398	  context: InvoiceContext,
399	  rows: Array<typeof schema.studentPaymentHistory.$inferSelect>,
400	) {
401	  if (userBalanceCents(context.student) >= 0) return false;
402	  const paidRows = rows.filter((row) => paymentContributionCents(row) > 0);
403	  if (paidRows.length === 0) return false;
404	  if (!paidRows.every(isAccountBalancePaymentHistoryRow)) return false;
405	  const paidCents = paidRows.reduce(
406	    (sum, row) => sum + paymentContributionCents(row),
407	    0,
408	  );
409	  return paidCents >= context.invoice.amount;
410	}
