428	async function invoicePaymentTotals(context: InvoiceContext) {
429	  const { invoice } = context;
430	  const rows = await paymentRowsForInvoice(invoice.flightSchoolId, invoice.id);
431	  const countAccountBalance = !hasLikelyUnfundedAccountBalanceSettlement(
432	    context,
433	    rows,
434	  );
435	  const paidCents = rows.reduce(
436	    (sum, row) => sum + paymentContributionCents(row, { countAccountBalance }),
437	    0,
438	  );
439	  const amountDueCents =
440	    isInvoiceMarkedPaid(invoice) && paidCents <= 0
441	      ? 0
442	      : Math.max(0, invoice.amount - paidCents);
443	  return { rows, paidCents, amountDueCents, countAccountBalance };
444	}
