555	function ensureSendable(
556	  context: InvoiceContext,
557	  amountDueCents: number,
558	  options: { allowDraft?: boolean } = {},
559	) {
560	  const { invoice } = context;
561	  const status = String(invoice.status ?? '').toLowerCase();
562	  if (isCreditLikeInvoice(invoice)) {
563	    throw new StudentInvoiceLinkServiceError(
564	      400,
565	      'CREDIT_INVOICE_NOT_PAYABLE',
566	      'Credit memos and refunds do not need invoice payment links.',
567	    );
568	  }
569	  if (!options.allowDraft && status === 'draft') {
570	    throw new StudentInvoiceLinkServiceError(
571	      409,
572	      'INVOICE_DRAFT',
573	      'Draft invoices must be finalized before sending.',
574	    );
575	  }
576	  if (NON_SENDABLE_STATUSES.has(status)) {
577	    throw new StudentInvoiceLinkServiceError(
578	      409,
579	      'INVOICE_NOT_SENDABLE',
580	      `Invoice cannot be sent while its status is ${invoice.status}.`,
581	    );
582	  }
583	  if (amountDueCents <= 0) {
584	    throw new StudentInvoiceLinkServiceError(
585	      409,
586	      'INVOICE_ALREADY_PAID',
587	      'This invoice does not have an amount due.',
588	    );
589	  }
590	}
