592	function paymentLinkStatus(
593	  context: InvoiceContext,
594	  amountDueCents: number,
595	): PublicInvoiceSummary['status'] {
596	  const { invoice } = context;
597	  const metadata = asMetadata(invoice.metadata);
598	  const paymentLink = asNestedMetadata(metadata.paymentLink);
599	  const expiresAt = cleanString(paymentLink.expiresAt);
600	  const status = String(invoice.status ?? '').toLowerCase();
601	  if (amountDueCents <= 0 || isInvoiceMarkedPaid(invoice)) return 'paid';
602	  if (NON_SENDABLE_STATUSES.has(status) && status !== 'draft') return 'void';
603	  if (expiresAt && new Date(expiresAt).getTime() < Date.now()) return 'expired';
604	  if (
605	    status.includes('pending sign-off') ||
606	    status.includes('pending review')
607	  ) {
608	    return 'pending';
609	  }
610	  return 'payable';
611	}
