654	export async function createStudentInvoicePaymentLink(args: {
655	  flightSchoolId: string;
656	  locationId: string;
657	  studentId: string;
658	  invoiceId: string;
659	  baseUrl: string;
660	  actor?: string | null;
661	  allowDraft?: boolean;
662	}) {
663	  const context = await getInvoiceContext(args);
664	  if (!context) {
665	    throw new StudentInvoiceLinkServiceError(
666	      404,
667	      'INVOICE_NOT_FOUND',
668	      'Invoice not found.',
669	    );
670	  }
671	
672	  const totals = await invoicePaymentTotals(context);
673	  ensureSendable(context, totals.amountDueCents, {
674	    allowDraft: args.allowDraft ?? true,
675	  });
676	
677	  const token = createPaymentToken();
678	  const tokenHash = hashPaymentToken(token);
679	  const now = new Date();
680	  const expiresAt = new Date(now.getTime() + PAYMENT_LINK_DAYS * DAY_MS);
681	  const url = `${args.baseUrl.replace(/\/$/, '')}/pay/invoice/${encodeURIComponent(token)}`;
682	  const metadata = asMetadata(context.invoice.metadata);
683	  const paymentLink = {
684	    tokenHash,
685	    createdAt: now.toISOString(),
686	    expiresAt: expiresAt.toISOString(),
687	    status: 'active',
688	    createdBy: args.actor ?? 'System',
689	  };
690	  const updatedMetadata = {
691	    ...metadata,
692	    paymentLink,
693	    paymentLinkCreatedAt: now.toISOString(),
694	    paymentLinkExpiresAt: expiresAt.toISOString(),
695	    customerFacingStatus:
696	      typeof metadata.customerFacingStatus === 'string'
697	        ? metadata.customerFacingStatus
698	        : 'Ready to Send',
699	  };
700	
701	  const [updatedInvoice] = await db
702	    .update(schema.studentInvoices)
703	    .set({ metadata: updatedMetadata, updatedAt: now })
704	    .where(
705	      and(
706	        eq(schema.studentInvoices.id, context.invoice.id),
707	        eq(schema.studentInvoices.flightSchoolId, args.flightSchoolId),
708	        eq(schema.studentInvoices.locationId, args.locationId),
709	        eq(schema.studentInvoices.studentId, args.studentId),
710	      ),
711	    )
712	    .returning();
713	
714	  return {
715	    invoice: updatedInvoice ?? context.invoice,
716	    paymentLink: {
717	      url,
718	      expiresAt: expiresAt.toISOString(),
719	      tokenHash,
720	    },
721	    amountDueCents: totals.amountDueCents,
722	  };
723	}
