1118	function stripeExpandableId(value: unknown) {
1119	  if (!value) return null;
1120	  if (typeof value === 'string') return value;
1121	  if (typeof value === 'object' && value !== null) {
1122	    const id = (value as { id?: unknown }).id;
1123	    return typeof id === 'string' ? id : null;
1124	  }
1125	  return null;
1126	}
1127	
1128	function paymentIntentLatestCharge(paymentIntent: Stripe.PaymentIntent) {
1129	  const latestCharge = paymentIntent.latest_charge;
1130	  if (!latestCharge || typeof latestCharge === 'string') return null;
1131	  return latestCharge as Stripe.Charge;
1132	}
1133	
1134	function processorFeeFromCharge(charge: Stripe.Charge | null) {
1135	  const balanceTransaction = charge?.balance_transaction;
1136	  if (
1137	    balanceTransaction &&
1138	    typeof balanceTransaction !== 'string' &&
1139	    typeof balanceTransaction.fee === 'number'
1140	  ) {
1141	    return balanceTransaction.fee;
1142	  }
1143	  return null;
1144	}
