1146	function paymentMethodLabel(paymentIntent: Stripe.PaymentIntent) {
1147	  const paymentMethod = paymentIntent.payment_method;
1148	  if (paymentMethod && typeof paymentMethod !== 'string') {
1149	    if (paymentMethod.type === 'card' && paymentMethod.card?.last4) {
1150	      return {
1151	        type: 'card',
1152	        label: `${paymentMethod.card.brand ?? 'Card'} ****${paymentMethod.card.last4}`,
1153	      };
1154	    }
1155	    if (
1156	      paymentMethod.type === 'us_bank_account' &&
1157	      paymentMethod.us_bank_account?.last4
1158	    ) {
1159	      return {
1160	        type: 'us_bank_account',
1161	        label: `ACH Bank ****${paymentMethod.us_bank_account.last4}`,
1162	      };
1163	    }
1164	    return { type: paymentMethod.type, label: 'Stripe Checkout' };
1165	  }
1166	
1167	  const charge = paymentIntentLatestCharge(paymentIntent);
1168	  const details = charge?.payment_method_details;
1169	  if (details?.type === 'card' && details.card?.last4) {
1170	    return {
1171	      type: 'card',
1172	      label: `${details.card.brand ?? 'Card'} ****${details.card.last4}`,
1173	    };
1174	  }
1175	  if (details?.type === 'us_bank_account' && details.us_bank_account?.last4) {
1176	    return {
1177	      type: 'us_bank_account',
1178	      label: `ACH Bank ****${details.us_bank_account.last4}`,
1179	    };
1180	  }
1181	  return { type: details?.type ?? null, label: 'Stripe Checkout' };
1182	}
