1184	function invoiceBalanceDeltaForStatusChange(args: {
1185	  oldStatus: string;
1186	  oldAmountCents: number;
1187	  oldBalanceImpactCents: number;
1188	  newStatus: string;
1189	  newAmountCents: number;
1190	}) {
1191	  const oldWasImpacting = BALANCE_IMPACTING_STATUSES.has(
1192	    args.oldStatus.toLowerCase(),
1193	  );
1194	  const newIsImpacting = BALANCE_IMPACTING_STATUSES.has(
1195	    args.newStatus.toLowerCase(),
1196	  );
1197	  const oldImpactCents =
1198	    args.oldBalanceImpactCents !== 0
1199	      ? args.oldBalanceImpactCents
1200	      : -args.oldAmountCents;
1201	  const newImpactCents = -args.newAmountCents;
1202	  return (
1203	    (newIsImpacting ? newImpactCents : 0) -
1204	    (oldWasImpacting ? oldImpactCents : 0)
1205	  );
