47	  'flight_time',
48	  'ground_time',
49	  'scheduled_duration',
50	  'actual_clock',
51	] as const;
52	
53	export type InstructionRateTimeBasis =
54	  (typeof INSTRUCTION_RATE_TIME_BASES)[number];
55	
56	export const INSTRUCTION_RATE_ELIGIBILITY_SCOPES = [
57	  'all_instructors',
58	  'lead_instructors',
59	] as const;
