71	export interface InstructionRateType {
72	  id: string;
73	  key: string;
74	  name: string;
75	  description?: string | null;
76	  defaultTimeBasis: InstructionRateTimeBasis;
77	  eligibilityScope: InstructionRateEligibilityScope;
78	  active: boolean;
79	  isSystem: boolean;
80	  sortOrder: number;
81	}
82	
83	const RATE_TYPE_KEY_PATTERN = /^[a-z][a-z0-9_]{1,63}$/;
84	
85	export function isInstructionRateTypeKey(value: unknown): value is string {
86	  return typeof value === 'string' && RATE_TYPE_KEY_PATTERN.test(value);
87	}
88	
89	export function isInstructionRateTimeBasis(
90	  value: unknown,
91	): value is InstructionRateTimeBasis {
92	  return (
93	    typeof value === 'string' &&
94	    (INSTRUCTION_RATE_TIME_BASES as readonly string[]).includes(value)
95	  );
96	}
97	
98	export function isInstructionRateEligibilityScope(
99	  value: unknown,
100	): value is InstructionRateEligibilityScope {
101	  return (
102	    typeof value === 'string' &&
103	    (INSTRUCTION_RATE_ELIGIBILITY_SCOPES as readonly string[]).includes(value)
104	  );
105	}
106	
107	export function isLeadInstructorRole(
108	  value: string | null | undefined,
109	): boolean {
110	  if (!value) return false;
111	  const normalized = value.trim().toLowerCase();
112	  return LEAD_INSTRUCTOR_ROLES.some(
113	    (role) => role.toLowerCase() === normalized,
114	  );
115	}
