117	export function isInstructorEligibleForInstructionRateType(
118	  rateType: Pick<InstructionRateType, 'eligibilityScope'>,
119	  instructorRole: string | null | undefined,
120	): boolean {
121	  return (
122	    rateType.eligibilityScope !== 'lead_instructors' ||
123	    isLeadInstructorRole(instructorRole)
124	  );
125	}
