135	export function instructionRateTypeKeyFromName(name: string): string {
136	  const normalized = name
137	    .trim()
138	    .toLowerCase()
139	    .replace(/[^a-z0-9]+/g, '_')
140	    .replace(/^_+|_+$/g, '')
141	    .slice(0, 64);
142	  if (!normalized) return '';
143	  return /^[a-z]/.test(normalized) ? normalized : `rate_${normalized}`;
144	}
