146	export function normalizeInstructionRateTypes(
147	  value: unknown,
148	): InstructionRateType[] {
149	  if (!Array.isArray(value)) return [];
150	  return value
151	    .map((item): InstructionRateType | null => {
152	      if (!item || typeof item !== 'object' || Array.isArray(item)) return null;
153	      const raw = item as Record<string, unknown>;
154	      const id = typeof raw.id === 'string' ? raw.id : '';
155	      const key = typeof raw.key === 'string' ? raw.key : '';
156	      const name = typeof raw.name === 'string' ? raw.name.trim() : '';
157	      if (!id || !isInstructionRateTypeKey(key) || !name) return null;
158	      return {
159	        id,
160	        key,
161	        name,
162	        description:
163	          typeof raw.description === 'string' ? raw.description : null,
164	        defaultTimeBasis: isInstructionRateTimeBasis(raw.defaultTimeBasis)
165	          ? raw.defaultTimeBasis
166	          : 'actual_clock',
167	        eligibilityScope: isInstructionRateEligibilityScope(
168	          raw.eligibilityScope,
169	        )
170	          ? raw.eligibilityScope
171	          : 'all_instructors',
172	        active: raw.active !== false,
173	        isSystem: raw.isSystem === true,
174	        sortOrder: Number.isFinite(Number(raw.sortOrder))
175	          ? Number(raw.sortOrder)
176	          : 0,
177	      };
178	    })
179	    .filter((item): item is InstructionRateType => item !== null)
180	    .sort(
181	      (left, right) =>
182	        left.sortOrder - right.sortOrder || left.name.localeCompare(right.name),
183	    );
184	}
