186	export function inferInstructionRateTypeKey(input: {
187	  requiresAircraft?: boolean;
188	  requiresSimulator?: boolean;
189	  quantitySource?: string;
190	  productId?: string;
191	  eventTypeName?: string;
192	}): string {
193	  const label =
194	    `${input.eventTypeName ?? ''} ${input.productId ?? ''}`.toLowerCase();
195	  if (label.includes('stage check') || label.includes('stage-check')) {
196	    return 'stage_check';
197	  }
198	  if (input.requiresSimulator || input.quantitySource === 'simulator_time') {
199	    return 'simulator_instruction';
200	  }
201	  if (
202	    label.includes('multi-engine') ||
203	    label.includes('multi engine') ||
204	    label.includes('mei')
205	  ) {
206	    return 'multi_engine_instruction';
207	  }
208	  if (input.quantitySource === 'ground_time') return 'ground_instruction';
209	  if (input.requiresAircraft || input.quantitySource === 'flight_time') {
210	    return 'flight_instruction';
211	  }
212	  return 'ground_instruction';
213	}
