1	import {
2	  inferInstructionRateTypeKey,
3	  isInstructionRateTypeKey,
4	  isInstructorEligibleForInstructionRateType,
5	} from '@/lib/billing/instruction-rate-types';
6	import { db } from '@/lib/db';
7	import {
8	  type ScheduleEvent,
9	  instructorCompensationSnapshots,
10	  instructorPayRates,
11	  users,
12	} from '@/lib/schema';
13	import { type SQL, and, desc, eq, gt, isNull, lte, or } from 'drizzle-orm';
14	import { ensureInstructionRateTypes } from './instruction-rate-type-service';
15	
16	type EventTypeFinancialConfig = Record<string, unknown> | null | undefined;
17	
18	function numberValue(value: unknown): number | null {
19	  const parsed = Number(value);
20	  return Number.isFinite(parsed) ? parsed : null;
21	}
22	
23	function roundHours(value: number): number {
24	  return Math.round(Math.max(0, value) * 100) / 100;
25	}
26	
27	function instructorRoleFromMetadata(metadata: unknown): string {
28	  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) {
29	    return 'Instructor';
30	  }
31	  const instructorRole = (metadata as Record<string, unknown>).instructorRole;
32	  return typeof instructorRole === 'string' && instructorRole.trim()
33	    ? instructorRole.trim()
34	    : 'Instructor';
35	}
36	
37	function elapsedHours(start: Date | null | undefined, end: Date): number {
38	  if (!start || Number.isNaN(start.getTime())) return 0;
39	  return roundHours((end.getTime() - start.getTime()) / 3_600_000);
40	}
41	
42	function resolvePayQuantity(args: {
43	  timeBasis: string;
44	  event: ScheduleEvent;
45	  body: Record<string, unknown>;
46	  completedAt: Date;
47	}): number {
48	  const { timeBasis, event, body, completedAt } = args;
49	  const hobbsOut =
50	    numberValue(body.hobbsOut) ??
51	    numberValue(body.hobbsOutActual) ??
52	    event.hobbsOutActual ??
53	    event.hobbsOut ??
54	    0;
55	  const hobbsIn = numberValue(body.hobbsIn) ?? event.hobbsIn ?? 0;
56	  const scheduled = elapsedHours(event.startAt, event.endAt);
57	  const preFlight = numberValue(body.preFlight) ?? event.preFlight ?? 0;
58	  const postFlight = numberValue(body.postFlight) ?? event.postFlight ?? 0;
59	
60	  if (timeBasis === 'aircraft_time' || timeBasis === 'flight_time') {
61	    return hobbsIn > 0 ? roundHours(Math.abs(hobbsIn - hobbsOut)) : scheduled;
62	  }
63	  if (timeBasis === 'simulator_time') {
64	    const logbookEntry =
65	      body.logbookEntry &&
66	      typeof body.logbookEntry === 'object' &&
67	      !Array.isArray(body.logbookEntry)
68	        ? (body.logbookEntry as Record<string, unknown>)
69	        : null;
70	    return roundHours(
71	      numberValue(logbookEntry?.totalTime) ??
72	        numberValue(body.totalTime) ??
73	        scheduled,
74	    );
75	  }
76	  if (timeBasis === 'ground_time') {
77	    const recordedGround = roundHours(preFlight + postFlight);
78	    return recordedGround > 0 ? recordedGround : scheduled;
79	  }
80	  if (timeBasis === 'actual_clock') {
81	    const checkout =
82	      body.checkedOutAt instanceof Date
83	        ? body.checkedOutAt
84	        : typeof body.checkedOutAt === 'string'
85	          ? new Date(body.checkedOutAt)
86	          : (event.checkedOutAt ?? event.actualStartTime);
87	    const actual = elapsedHours(checkout, completedAt);
88	    return actual > 0 ? actual : scheduled;
89	  }
90	  return scheduled;
91	}
