93	export async function snapshotInstructorCompensationForCompletedEvent(args: {
94	  flightSchoolId: string;
95	  locationId: string;
96	  event: ScheduleEvent;
97	  updatedEvent: ScheduleEvent;
98	  eventTypeId: string;
99	  eventTypeConfig: EventTypeFinancialConfig;
100	  body: Record<string, unknown>;
101	}) {
102	  if (args.eventTypeConfig?.instructorUnpaid === true) return [];
103	
104	  const instructorIds = [
105	    args.updatedEvent.instructorId,
106	    ...(Array.isArray(args.updatedEvent.instructorIds)
107	      ? args.updatedEvent.instructorIds
108	      : []),
109	  ].filter(
110	    (value, index, values): value is string =>
111	      typeof value === 'string' &&
112	      value.length > 0 &&
113	      values.indexOf(value) === index,
114	  );
115	  if (instructorIds.length === 0) return [];
116	
117	  const configuredRateTypeKey = args.eventTypeConfig?.instructorPayRateTypeKey;
118	  const activityKey = isInstructionRateTypeKey(configuredRateTypeKey)
119	    ? configuredRateTypeKey
120	    : inferInstructionRateTypeKey({
121	        requiresAircraft: Boolean(args.eventTypeConfig?.requiresAircraft),
122	        requiresSimulator: Boolean(args.eventTypeConfig?.requiresSimulator),
123	        eventTypeName:
124	          typeof args.eventTypeConfig?.name === 'string'
125	            ? args.eventTypeConfig.name
126	            : args.updatedEvent.title,
127	      });
128	  const rateTypes = await ensureInstructionRateTypes({
129	    flightSchoolId: args.flightSchoolId,
130	    locationId: args.locationId,
131	  });
132	  const rateType = rateTypes.find((candidate) => candidate.key === activityKey);
133	  const configuredTimeBasis = args.eventTypeConfig?.instructorPayQuantitySource;
134	  const timeBasis =
135	    typeof configuredTimeBasis === 'string'
136	      ? configuredTimeBasis
137	      : (rateType?.defaultTimeBasis ?? 'scheduled_duration');
138	  const completedAt = args.updatedEvent.completedAt ?? new Date();
139	  const effectiveDate = completedAt.toISOString().slice(0, 10);
140	  const quantity = resolvePayQuantity({
141	    timeBasis,
142	    event: args.updatedEvent,
143	    body: args.body,
144	    completedAt,
145	  });
146	
147	  const effectiveRange = (subjectCondition: SQL | undefined) =>
148	    and(
149	      eq(instructorPayRates.flightSchoolId, args.flightSchoolId),
150	      eq(instructorPayRates.locationId, args.locationId),
151	      eq(instructorPayRates.activityKey, activityKey),
152	      eq(instructorPayRates.status, 'active'),
153	      lte(instructorPayRates.effectiveFrom, effectiveDate),
154	      or(
155	        isNull(instructorPayRates.effectiveTo),
156	        gt(instructorPayRates.effectiveTo, effectiveDate),
157	      ),
158	      subjectCondition,
159	    );
160	
161	  const [locationRate] = await db
162	    .select()
163	    .from(instructorPayRates)
164	    .where(
165	      effectiveRange(
166	        and(
167	          eq(instructorPayRates.subjectType, 'location'),
168	          eq(instructorPayRates.subjectId, args.locationId),
169	          isNull(instructorPayRates.instructorId),
170	        ),
171	      ),
172	    )
173	    .orderBy(desc(instructorPayRates.effectiveFrom))
174	    .limit(1);
175	
176	  const snapshots = [];
177	  for (const instructorId of instructorIds) {
178	    const [instructor] = await db
179	      .select({ instructorMetadata: users.instructorMetadata })
180	      .from(users)
181	      .where(
182	        and(
183	          eq(users.id, instructorId),
184	          eq(users.flightSchoolId, args.flightSchoolId),
185	          eq(users.role, 'instructor'),
186	        ),
187	      )
188	      .limit(1);
189	    const instructorRole = instructorRoleFromMetadata(
190	      instructor?.instructorMetadata,
191	    );
192	    const eligible =
193	      !rateType ||
194	      isInstructorEligibleForInstructionRateType(rateType, instructorRole);
195	    const instructorRate = eligible
196	      ? (
197	          await db
198	            .select()
199	            .from(instructorPayRates)
200	            .where(
201	              effectiveRange(
202	                and(
203	                  eq(instructorPayRates.subjectType, 'instructor'),
204	                  eq(instructorPayRates.instructorId, instructorId),
205	                ),
206	              ),
207	            )
208	            .orderBy(desc(instructorPayRates.effectiveFrom))
209	            .limit(1)
210	        )[0]
211	      : undefined;
212	    const rate = eligible ? (instructorRate ?? locationRate) : undefined;
213	    const reviewReason = !eligible
214	      ? `${rateType?.name ?? activityKey} requires a lead instructor; ${instructorRole} is not eligible.`
215	      : rate
216	        ? null
217	        : `No effective instructor or location pay rate for ${rateType?.name ?? activityKey}.`;
218	    const amountCents = rate
219	      ? Math.round(quantity * Math.max(0, rate.rateCents))
220	      : 0;
221	    const [snapshot] = await db
222	      .insert(instructorCompensationSnapshots)
223	      .values({
224	        flightSchoolId: args.flightSchoolId,
225	        locationId: args.locationId,
226	        eventId: args.updatedEvent.id,
227	        eventTypeId: args.eventTypeId || null,
228	        instructorId,
229	        activityKey,
230	        activityName: rateType?.name ?? activityKey,
231	        quantity: quantity.toFixed(2),
232	        unit: 'hour',
233	        timeBasis,
234	        rateCents: rate?.rateCents ?? null,
235	        amountCents,
236	        payRateId: rate?.id ?? null,
237	        effectiveDate,
238	        status: rate ? 'resolved' : 'payroll_review',
239	        reviewReason,
240	      })
241	      .onConflictDoNothing()
242	      .returning();
243	    if (snapshot) snapshots.push(snapshot);
244	  }
245	  return snapshots;
246	}
