29	// ═══════════════════════════════════════════════════════════════════════════
30	// GET /finance/overview — all finance data for the super admin dashboard
31	// ═══════════════════════════════════════════════════════════════════════════
32	finance.get('/finance/overview', requireAdmin(), async (c) => {
33	  try {
34	    const { fromDate, toDate } = parseDateRange(c);
35	
36	    const [dbLocations, dbEquipmentCounts, dbInvoicesRaw, billingSchools] =
37	      await Promise.all([
38	        financeRepository.findAllLocations(),
39	        financeRepository.findEquipmentCountsByType(),
40	        financeRepository.findAllInvoices(),
41	        poeBillingRepository.findAllSchoolsBillingDashboard(),
42	      ]);
43	
44	    // Build billing lookup by school ID
45	    const billingMap = new Map(billingSchools.map((s) => [s.schoolId, s]));
46	
47	    // Build a per-location equipment count map
48	    const locEqMap: Record<string, { aircraft: number; simulators: number }> =
49	      {};
50	    for (const row of dbEquipmentCounts) {
51	      const locId = row.locationId ?? '';
52	      if (!locEqMap[locId]) locEqMap[locId] = { aircraft: 0, simulators: 0 };
53	      if (row.type === 'Aircraft') locEqMap[locId].aircraft += row.count;
54	      else if (row.type === 'Simulator')
55	        locEqMap[locId].simulators += row.count;
56	    }
57	
58	    // Enrich location rows with computed aircraft/simulator counts
59	    const locations: Array<{
60	      id: string;
61	      name: string;
62	      city: string | null;
63	      state: string | null;
64	      status: string | null;
65	      flightSchoolId: string;
66	      schoolId: string;
67	      schoolName: string;
68	      aircraftCount: number;
69	      simulatorCount: number;
70	      studentCount: number;
71	      instructorCount: number;
72	    }> = dbLocations.map((loc) => ({
73	      ...loc,
74	      schoolId: loc.flightSchoolId,
75	      schoolName: billingMap.get(loc.flightSchoolId)?.schoolName ?? loc.name,
76	      aircraftCount: locEqMap[loc.id]?.aircraft ?? 0,
77	      simulatorCount: locEqMap[loc.id]?.simulators ?? 0,
78	      studentCount: 0,
79	      instructorCount: 0,
80	    }));
81	
82	    let mergedInvoices: Record<string, unknown>[] = dbInvoicesRaw.map(
83	      (inv) => ({
84	        id: inv.id,
85	        schoolId: inv.flightSchoolId,
86	        schoolName: billingMap.get(inv.flightSchoolId)?.schoolName ?? 'Unknown',
87	        amount: inv.amount / 100,
88	        status: inv.status,
89	        date: inv.createdAt?.toISOString(),
90	        periodStart: inv.periodStart?.toISOString(),
91	        periodEnd: inv.periodEnd?.toISOString(),
92	        paidAt: inv.paidAt?.toISOString(),
93	        poeCount: inv.poeCount,
94	        taxAmount: (inv.taxAmount ?? 0) / 100,
95	        invoiceUrl: inv.invoiceUrl,
96	        stripeInvoiceId: inv.stripeInvoiceId,
97	      }),
98	    );
99	
100	    // Apply date range filter to invoices
101	    if (fromDate || toDate) {
102	      mergedInvoices = mergedInvoices.filter((inv) => {
103	        const dateStr = (inv.date || inv.periodEnd) as string | undefined;
104	        if (!dateStr) return true;
105	        const d = new Date(dateStr);
106	        if (Number.isNaN(d.getTime())) return true;
107	        if (fromDate && d < fromDate) return false;
108	        if (toDate) {
109	          const toEnd = new Date(toDate);
110	          toEnd.setHours(23, 59, 59, 999);
111	          if (d > toEnd) return false;
112	        }
113	        return true;
114	      });
115	    }
116	
117	    // ─── Filter out E2E / test schools and admin accounts ───
118	    const isExcludedSchool = (name: string) =>
119	      /\be2e\b|test\s*(campus|school|location)|^hilo\s*aviation$/i.test(name);
120	
121	    // Build a set of excluded school IDs so ALL downstream data is filtered
122	    const excludedSchoolIds = new Set(
123	      billingSchools
124	        .filter((sc) => isExcludedSchool(sc.schoolName))
125	        .map((sc) => sc.schoolId),
126	    );
127	    for (const loc of dbLocations) {
128	      const name = billingMap.get(loc.flightSchoolId)?.schoolName ?? loc.name;
129	      if (isExcludedSchool(name)) excludedSchoolIds.add(loc.flightSchoolId);
130	    }
131	    // Exclude flagged test schools (is_test) from the invoice/location breakdown.
132	    // (MRR/POE/run-rate are already excluded at source via
133	    // poeBillingRepository.findAllSchoolsBillingDashboard().)
134	    for (const id of await financeRepository.findTestSchoolIds()) {
135	      excludedSchoolIds.add(id);
136	    }
137	
138	    const realBillingSchools = billingSchools.filter(
139	      (sc) => !excludedSchoolIds.has(sc.schoolId),
140	    );
141	
142	    // Filter excluded schools from invoices and locations
143	    mergedInvoices = mergedInvoices.filter(
144	      (inv) => !excludedSchoolIds.has(inv.schoolId as string),
145	    );
146	    const filteredLocations = locations.filter(
147	      (loc) => !excludedSchoolIds.has(loc.schoolId),
148	    );
149	
150	    // ─── MRR from billing-accurate data ───
151	    const currentMRR = realBillingSchools.reduce(
152	      (s, sc) => s + sc.monthlyChargeCents / 100,
153	      0,
154	    );
155	    const totalPOE = realBillingSchools.reduce((s, sc) => s + sc.peakPoe, 0);
156	    const failedPayments = realBillingSchools.filter(
157	      (sc) =>
158	        sc.billingStatus === 'Failed' || sc.billingStatus === 'Payment Failed',
